/* ---- bienvenida del examen con fotos ---- */
.fx-wlogo{width:min(210px,55vw);height:auto;display:block;margin:0 auto 12px}
.fx-photos{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:6px 0 14px}
.fx-pbox{border:1.5px solid var(--bd);border-radius:16px;overflow:hidden;background:#fff;box-shadow:0 6px 18px rgba(11,42,91,.12)}
.fx-pimg{aspect-ratio:4/3;background:#eee}.fx-pimg img{width:100%;height:100%;object-fit:cover;display:block}
.fx-pcap{border-top:1.5px solid var(--bd);background:var(--y3);padding:6px 4px;font-weight:800;font-size:14px}
.fx-pcap b{font-family:var(--fh);font-size:18px}
.fx-info{display:flex;gap:12px;align-items:center;text-align:left;background:var(--y3);border:2.5px dashed var(--k);border-radius:14px;padding:10px 14px;margin:0 auto 16px;max-width:620px}
.fx-wmra{height:110px;width:auto;flex:none}
@media (max-width:600px){.fx-photos{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.fx-wmra{height:80px}}


/* ================= v18: tema Rojo · Azul · Blanco ================= */
.player{max-width:min(860px,100%)}
.wrap{max-width:min(1100px,100%)}
/* texto blanco sobre rojo */
.btn,.brand small,.pill.y,.topbar .pill.y,.hello h1 .nm,.topic .num,.partbtn:hover,.ph .tc,.play,.aud,.msg .av,.slot.f,.xpfly,.trow .n,.mascot-box .tipday,#dict-fab,.kn,.tile.blink,.chat-head,.cm.me .bub,.qs-l,.fx-opts .opt .qs-l,.chat-ic,.iconbtn:hover{color:#fff}
.btn.w,.btn.w:hover{color:var(--k)}
.btn.k{background:var(--k);color:#fff}
.chat-head small{color:#fff!important}
.ph .tc.dark{background:var(--k);color:#fff}
.brand small{border-color:var(--k)}
/* resaltados en azul suave (no rojo) */
.reading .txt .s.on,.ws-c.sel,.ml-b.sel,.cat.hot,.ws-c.show{background:#CFE0FA;color:var(--k)}
.lbl{background:var(--k);color:#fff}
.secbar span.on{background:var(--y);border-color:var(--y);color:#fff}
.final{background:var(--k)}
.final h3{color:#fff}
.inp:focus,textarea.hw:focus{box-shadow:0 0 0 4px #BFD6F8}
.toast{border-color:var(--y)}
.tour-hole{border-color:var(--y)}
.cert2{background:linear-gradient(135deg,var(--y) 0 50%,var(--k) 50% 100%)}
.cert:before{border-color:var(--y)}
.opt.right,.right{border-color:#15803d}
.mascot-box{background:#fff}
.topbar{border-bottom:4px solid var(--y)}
.bsky{border-color:#93B8EE;background:linear-gradient(#EAF2FD,#fff)}
.bub{border-color:var(--blue)}
.qs-opts .opt{background:var(--k);border-color:var(--y)}
.chat-ic svg path:first-child{fill:#fff}
.chat-ic svg circle{fill:var(--y)}
.chat-ic svg path:last-child{stroke:#fff}
.fx-chip.t{background:var(--k);color:#fff}
/* separación entre el botón 🔊 y el cuadro de escribir */
.stage .play{margin-bottom:22px}
.stage .play + .inp,.stage .hintline + .inp{margin-top:8px}
@media (min-width:701px){.stage .inp{max-width:620px;display:block;margin-left:auto;margin-right:auto}}
.chip.blink{animation:blink .5s 4;background:#CFE0FA!important}

/* ---- juegos dinámicos v18 ---- */
.cw-hud{display:flex;justify-content:space-between;align-items:center;gap:8px;font-weight:800;margin-bottom:8px;flex-wrap:wrap}
.cw-clue{font-family:var(--fh);font-size:clamp(18px,4.6vw,22px);display:flex;align-items:center;gap:8px;color:var(--y)}
.cw-sky{position:relative;height:360px;border:1.5px solid var(--bd);border-radius:18px;overflow:hidden;background:linear-gradient(#D6E6FB,#fff 70%)}
.cw-ground{position:absolute;left:0;right:0;bottom:0;height:34px;background:#4ade80;border-top:1.5px solid var(--bd);text-align:center;font-size:16px;line-height:30px;overflow:hidden;white-space:nowrap}
.cw-word{position:absolute;top:-80px;width:28%;max-width:200px;border:1.5px solid var(--bd);border-radius:14px;background:#fff;font-family:var(--fh);font-weight:800;font-size:clamp(14px,3.8vw,18px);padding:6px 4px;line-height:1.2;color:var(--k);box-shadow:0 6px 18px rgba(11,42,91,.12);animation:fall var(--t) linear var(--d) forwards;overflow-wrap:anywhere}
@keyframes fall{to{top:calc(100% - 34px)}}
.cw-word.got{background:#86efac;transform:scale(1.15)}.cw-word.right{background:#bbf7d0;border-color:#15803d}.cw-word.wrong{background:#fecaca}
.sw-wrap{position:relative;width:min(320px,80vw);aspect-ratio:1;margin:6px auto 14px}
.sw-pin{position:absolute;top:-14px;left:50%;transform:translateX(-50%);z-index:2;font-size:34px;color:var(--y);text-shadow:0 2px 0 var(--k)}
.sw-wheel{width:100%;height:100%;border-radius:50%;border:5px solid var(--k);position:relative;box-shadow:0 6px 18px rgba(11,42,91,.12)}
.sw-wheel span{position:absolute;left:50%;top:50%;width:0;height:50%;transform-origin:0 0}
.sw-wheel span i{position:absolute;left:-14px;top:-45%;width:28px;text-align:center;font-style:normal;font-family:var(--fh);font-weight:800;font-size:20px}
.sw-wheel span{transform-origin:0 0;top:50%;height:0}
.sw-hub{position:absolute;inset:38%;border-radius:50%;background:#fff;border:1.5px solid var(--bd);display:grid;place-items:center;font-family:var(--fh);color:var(--y)}
.sw-card{border:1.5px solid var(--bd);border-radius:16px;background:var(--y3);padding:12px;text-align:center;margin-top:6px}
.sw-card small{font-weight:800;color:var(--y)}.sw-es{font-family:var(--fh);font-weight:800;font-size:clamp(24px,6vw,32px)}
.rc-track{display:grid;gap:10px;margin-bottom:12px}
.rc-lane{display:grid;grid-template-columns:90px minmax(0,1fr);align-items:center;gap:8px}
.rc-name{font-weight:800;font-size:14px}
.rc-road{position:relative;height:52px;border:1.5px solid var(--bd);border-radius:12px;background:repeating-linear-gradient(90deg,#4A5B78 0 30px,#3B4A63 30px 60px);overflow:hidden}
.rc-road:after{content:"";position:absolute;left:0;right:0;top:50%;border-top:3px dashed #fff}
.rc-car{position:absolute;top:2px;width:46px;height:42px;display:grid;place-items:center;font-size:34px;transition:left .8s cubic-bezier(.3,1.4,.5,1);z-index:1}
.rc-car img{height:42px;width:auto;object-fit:contain;filter:drop-shadow(0 2px 0 #000)}
.rc-flag{position:absolute;right:4px;top:8px;font-size:26px}
.sp-sky{min-height:300px;display:flex;flex-wrap:wrap;gap:16px;justify-content:center;align-content:center;padding:16px;border:3px dashed #93B8EE;border-radius:18px;background:linear-gradient(#EAF2FD,#fff)}
.sp-ball{position:relative;width:clamp(96px,28vw,130px);height:clamp(116px,34vw,156px);border-radius:50% 50% 48% 48%;border:1.5px solid var(--bd);background:radial-gradient(circle at 30% 28%,rgba(255,255,255,.75),transparent 34%),var(--c);color:#fff;font-family:var(--fh);font-weight:800;font-size:clamp(14px,3.8vw,18px);padding:8px;overflow-wrap:anywhere;animation:float 2.8s ease-in-out infinite;animation-delay:var(--d);text-shadow:0 1px 2px rgba(0,0,0,.5)}
.sp-ball i{position:absolute;left:50%;bottom:-26px;width:2px;height:24px;background:var(--k)}
.sp-ball.pop{animation:pop2 .45s forwards}.sp-ball.shake{animation:shake .4s}
@media (max-width:600px){.cw-sky{height:330px}.rc-lane{grid-template-columns:70px minmax(0,1fr)}.cw-word{width:30%}}
.sw-n{position:absolute;font-style:normal;font-family:var(--fh);font-weight:800;font-size:22px;line-height:1}
.dict-q{font-weight:700;color:var(--mut);margin-top:8px}
/* v21 — parte en curso resaltada en verde */
.partbtn.cur{background:#DDF7E6!important;border-color:#16A34A!important;box-shadow:0 4px 0 #15803D!important}
.partbtn.cur .t,.partbtn.cur small{color:#0B3D22}
.partbtn .curtag{display:inline-block;margin-left:6px;background:#16A34A;color:#fff;font-size:11px;letter-spacing:.5px;padding:2px 8px;border-radius:999px;vertical-align:middle}
/* ===================== v22 — juegos únicos por clase ===================== */
.g3-opts{margin-top:12px}
.g3-opts .opt{font-size:17px;padding:12px 10px}
.g3-three{grid-template-columns:repeat(3,1fr)}
.g3-two{grid-template-columns:1fr 1fr}
.g3-img .opt{padding:0}
@media(min-width:761px){.g3-img{grid-template-columns:repeat(4,1fr)}.g3-opts:not(.g3-img){max-width:640px;margin-left:auto;margin-right:auto}}
.g3-menu{grid-template-columns:repeat(3,1fr)}
@media(max-width:520px){.g3-menu{grid-template-columns:repeat(2,1fr)}.g3-three{grid-template-columns:1fr}}
.opt.sel{outline:4px solid var(--blue);background:var(--y3);transform:translateY(-2px)}
.g3-fb{margin:14px auto 4px;max-width:640px;border-radius:14px;padding:12px 14px;font-weight:700;border:2px solid;text-align:center;font-size:17px;line-height:1.35}
.g3-fb b{display:block;font-family:var(--fh);font-size:20px;color:var(--k)}
.g3-fb span{display:block;font-weight:600;color:#475569;font-style:italic;font-size:15px}
.g3-fb.ok{background:#DCFCE7;border-color:#16A34A;color:#166534}
.g3-fb.no{background:#FEE2E2;border-color:var(--y);color:#991B1B}
.g3-rep{margin:6px auto 0}
.g3-st{font-weight:700;min-height:24px}
.g3-sent{text-align:center;font-family:var(--fh);font-weight:800;font-size:21px;color:var(--k);margin:12px auto 4px;max-width:600px;line-height:1.3}
.g3-sent u{color:var(--y);text-decoration:none;border-bottom:3px dashed var(--y)}
.g3-sent small,.g3-officer small,.g3-msg small,.g3-clue small,.g3-trip small{display:block;font-family:var(--fb,inherit);font-weight:600;font-size:14px;color:#64748B;font-style:italic;margin-top:3px}
.g3-call{text-align:center;font-family:var(--fh);font-size:19px;background:var(--k);color:#fff;border-radius:14px;padding:10px 14px;margin:0 auto 12px;max-width:520px}
.g3-call b{color:#fff}.g3-call small{opacity:.8;font-size:13px}
/* reloj */
.g3-sky{border-radius:18px;padding:18px;text-align:center;color:#fff;border:1.5px solid var(--bd);max-width:520px;margin:0 auto}
.g3-sky.morning{background:linear-gradient(#FDBA74,#FDE68A);color:var(--k)}.g3-sky.afternoon{background:linear-gradient(#60A5FA,#BFDBFE);color:var(--k)}
.g3-sky.evening{background:linear-gradient(#7C3AED,#F97316)}.g3-sky.night{background:linear-gradient(#0B2A5B,#1E293B)}
.g3-ic{font-size:48px;line-height:1}.g3-time{font-family:var(--fh);font-size:48px;font-weight:900;letter-spacing:2px}.g3-time small{font-size:20px;margin-left:6px}
.g3-sky p{margin:6px 0 0;font-weight:700;font-size:16px}
/* chat */
.g3-phone{max-width:420px;margin:0 auto;border:1.5px solid var(--bd);border-radius:26px;overflow:hidden;background:#ECE5DD}
.g3-ph-top{background:#075E54;color:#fff;padding:10px 14px;font-size:16px}.g3-ph-top small{opacity:.8;margin-left:6px}
.g3-msgs{height:230px;overflow-y:auto;padding:10px;display:flex;flex-direction:column;gap:6px}
.g3-msg{max-width:82%;padding:8px 11px;border-radius:12px;font-weight:600;font-size:15px;box-shadow:0 1px 1px rgba(0,0,0,.15)}
.g3-msg.in{background:#fff;align-self:flex-start;border-top-left-radius:2px}
.g3-msg.out{background:#DCF8C6;align-self:flex-end;border-top-right-radius:2px}.g3-msg.out.fix{background:#FFE4E6}
.g3-msg.typing{color:#94a3b8;letter-spacing:2px}
/* simon */
.g3-seq{display:flex;justify-content:center;gap:8px;margin-bottom:12px}
.g3-seq i{font-style:normal;width:48px;height:56px;border:3px dashed var(--k);border-radius:12px;display:grid;place-items:center;font-family:var(--fh);font-size:26px;font-weight:900;color:var(--k);background:#fff}
.g3-seq i.ok{border-style:solid;background:#DCFCE7}
.g3-pad{display:grid;grid-template-columns:repeat(auto-fill,minmax(54px,1fr));gap:8px;max-width:520px;margin:0 auto}
.g3-pad button{font-family:var(--fh);font-size:24px;font-weight:900;padding:10px 0;border:1.5px solid var(--bd);border-radius:12px;background:#fff;color:var(--k);box-shadow:0 6px 18px rgba(11,42,91,.12)}
.g3-pad button.lit{background:var(--y);color:#fff;transform:scale(1.12)}
.shake{animation:shake .35s}
/* placa */
.g3-plate{max-width:300px;margin:0 auto 6px;background:#FACC15;border:5px solid #111;border-radius:14px;text-align:center;padding:6px 10px;font-family:var(--fh);color:#111;box-shadow:0 6px 0 #0B2A5B}
.g3-plate div{font-size:44px;font-weight:900;letter-spacing:3px;line-height:1.1}.g3-plate small{font-size:11px;font-weight:800;letter-spacing:2px}
.g3-inwrap{max-width:240px;margin:6px auto}.g3-in{text-align:center;font-size:26px!important;letter-spacing:6px;text-transform:uppercase;font-weight:900}
/* pasaporte */
.g3-pass{max-width:520px;margin:0 auto 12px;background:#0B2A5B;border-radius:14px;padding:8px;color:#fff}
.g3-pass-h{font-family:var(--fh);font-size:12px;letter-spacing:3px;text-align:center;margin-bottom:6px}
.g3-stamps{background:#F7FAFF;border-radius:10px;min-height:48px;display:flex;flex-wrap:wrap;gap:6px;padding:8px;align-items:center;justify-content:center}
.g3-stamps em{color:#64748B;font-size:14px}
.g3-stamps span{border:2px solid var(--y);color:var(--y);border-radius:8px;padding:2px 8px;font-family:var(--fh);font-weight:900;font-size:13px;transform:rotate(-6deg);text-transform:uppercase}
.g3-flag{max-width:260px;margin:0 auto}.g3-flag .ph{aspect-ratio:3/2}
/* aeropuerto / restaurante */
.g3-officer{display:flex;align-items:center;justify-content:center;gap:10px;font-size:52px;margin:0 auto 10px;max-width:560px}
.g3-officer .bubble{font-size:18px;font-family:var(--fh);font-weight:800}
.g3-desk{max-width:560px;margin:0 auto}
.g3-card{display:flex;gap:12px;align-items:center;background:#fff;border:1.5px solid var(--bd);border-radius:14px;padding:10px;box-shadow:var(--sh)}
.g3-card small{display:block;font-size:11px;letter-spacing:2px;color:#64748B;font-weight:800}.g3-card b{font-size:20px;font-family:var(--fh);color:var(--k)}
.g3-mini{width:90px;flex:none}.g3-mini .ph{aspect-ratio:3/2}
/* bingo */
.g3-bingo{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-width:340px;margin:0 auto 10px}
.g3-bingo button{aspect-ratio:1;border:1.5px solid var(--bd);border-radius:14px;background:#fff;font-family:var(--fh);color:var(--k);display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 6px 18px rgba(11,42,91,.12)}
.g3-bingo b{font-size:34px;line-height:1}.g3-bingo small{font-size:12px;font-weight:700;min-height:14px}
.g3-bingo button.on{background:var(--y);color:#fff;border-color:var(--y)}
.g3-bingo-yell{position:fixed;left:50%;top:40%;transform:translate(-50%,-50%);background:var(--y);color:#fff;font-family:var(--fh);font-size:44px;font-weight:900;padding:16px 28px;border-radius:20px;border:3px solid #fff;box-shadow:0 10px 30px rgba(0,0,0,.3);z-index:90;animation:pop .4s}
/* colores */
.g3-mix{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;margin:6px 0}
.g3-mix>b{font-size:30px;color:var(--k)}
.g3-pot{width:88px;height:88px;border-radius:50%;background:var(--c);border:1.5px solid var(--bd);display:flex;align-items:flex-end;justify-content:center;transition:background .6s}
.g3-pot span{background:#fff;border:1.5px solid var(--bd);border-radius:8px;padding:0 6px;font-weight:800;font-size:14px;margin-bottom:-12px}
.g3-pot.q span{font-size:18px}.g3-pot.fill{animation:pop .5s}
.g3-dot{display:inline-block;width:16px;height:16px;border-radius:50%;border:1.5px solid var(--bd);vertical-align:-2px;margin-right:4px}
/* tragamonedas */
.g3-slot{display:flex;gap:6px;justify-content:center;background:linear-gradient(#E3242B,#B91C1C);border:1.5px solid var(--bd);border-radius:18px;padding:10px;max-width:560px;margin:0 auto 12px;flex-wrap:wrap}
.g3-reel{background:#fff;border:1.5px solid var(--bd);border-radius:10px;min-width:80px;padding:12px 10px;text-align:center;font-family:var(--fh);font-size:24px;font-weight:900;color:var(--k)}
.g3-reel.v{color:var(--y)}.g3-reel.r{font-size:18px;display:flex;align-items:center}
.g3-slot.spin .g3-reel:first-child{animation:shake .15s infinite}
/* topos */
.g3-holes{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;max-width:420px;margin:8px auto;background:#86EFAC;border:1.5px solid var(--bd);border-radius:18px;padding:12px}
.g3-hole{height:78px;background:radial-gradient(ellipse at 50% 85%,#5B3A1A 0 38%,transparent 40%);position:relative;overflow:hidden}
.g3-mole{position:absolute;left:8%;right:8%;bottom:-70px;height:62px;border-radius:30px 30px 10px 10px;background:#8B5A2B;color:#fff;border:1.5px solid var(--bd);font-weight:800;font-size:14px;transition:bottom .18s;padding:0 2px}
.g3-mole.up{bottom:6px}.g3-hole.bonk .g3-mole{background:#16A34A}
/* adivinanzas */
.g3-clues{max-width:560px;margin:0 auto}
.g3-clue{background:#fff;border:1.5px solid var(--bd);border-left:10px solid var(--y);border-radius:12px;padding:10px 12px;margin-bottom:8px;font-weight:700;font-size:17px;animation:pop .3s}
/* elevador */
.g3-bld{max-width:300px;margin:0 auto;border:1.5px solid var(--bd);border-radius:10px 10px 0 0;background:#fff}
.g3-floor{display:flex;align-items:center;gap:8px;height:34px;border-bottom:2px solid #CBD5E1;padding:0 8px;font-weight:700;font-size:14px;color:var(--k)}
.g3-floor span{width:22px;height:22px;border-radius:50%;background:var(--y3);display:grid;place-items:center;font-size:12px;font-weight:900}
.g3-floor.done{background:#DCFCE7}.g3-floor.cur{background:var(--y2);font-size:20px}
/* árbol */
.g3-tree{max-width:520px;margin:0 auto;display:flex;flex-direction:column;gap:10px;background:#F0FDF4;border:1.5px solid var(--bd);border-radius:16px;padding:12px 6px}
.g3-trow{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}
.g3-node{width:74px;text-align:center;font-size:30px;background:#fff;border:2px solid #CBD5E1;border-radius:12px;padding:4px 2px}
.g3-node b{display:block;font-size:13px;color:var(--k)}.g3-node small{display:block;font-size:11px;color:#16A34A;font-weight:800;min-height:13px}
.g3-node.me{border-color:var(--blue);background:var(--y3)}.g3-node.me small{color:var(--blue)}
.g3-node.hl{border-color:var(--y);background:var(--y2);transform:scale(1.1);box-shadow:0 0 0 4px rgba(227,36,43,.25)}
/* sonidos */
.g3-snd{text-align:center;margin-bottom:6px}.g3-snd .bubble{font-size:30px;font-family:var(--fh);font-weight:900;display:inline-block}
/* bandeja / lista */
.g3-tray{max-width:560px;margin:12px auto 0;text-align:center;background:var(--y3);border:3px dashed var(--k);border-radius:14px;padding:10px;font-weight:700}
.g3-list{max-width:420px;margin:0 auto 10px;background:#FFFBEB;border:1.5px solid var(--bd);border-radius:12px;padding:10px 14px;display:flex;flex-direction:column;gap:4px;font-size:17px;font-weight:700}
.g3-list span.ok{color:#16A34A;text-decoration:line-through}
/* calendario */
.g3-cal{max-width:240px;margin:0 auto;background:#fff;border:1.5px solid var(--bd);border-radius:14px;overflow:hidden;text-align:center;transition:transform .5s}
.g3-cal-top{background:var(--y);color:#fff;font-family:var(--fh);font-weight:900;letter-spacing:2px;padding:6px;font-size:14px}
.g3-cal-d{font-family:var(--fh);font-size:34px;font-weight:900;color:var(--k);padding:12px 6px}
.g3-cal-d.sm{font-size:22px;padding:8px 6px 2px}.g3-cal small{display:block;color:#64748B;font-weight:700;padding:0 6px 10px}
.g3-cal.big .g3-cal-top{font-size:40px;padding:4px}
.g3-cal.flip{transform:rotateX(360deg)}
/* TV clima */
.g3-tv{max-width:560px;margin:0 auto;background:#0B2A5B;border:6px solid #111;border-radius:16px;padding:8px}
.g3-tv-h{color:#fff;font-weight:800;font-size:12px;letter-spacing:2px;margin-bottom:6px}
.g3-tv-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
.g3-tv-grid div{background:#1D5FD1;border-radius:10px;text-align:center;color:#fff;padding:6px 2px}
