.g5b-bridge{position:relative;display:grid;grid-template-columns:1fr 1.2fr 1fr;align-items:end;height:110px;max-width:520px;margin:0 auto;background:linear-gradient(180deg,#BFE3FF,#EAF6FF);border:1.5px solid var(--bd);border-radius:16px;overflow:hidden}
