/* BEGIN g6c */
/* ===================== g6c — Módulo 4 · C1 debates (t15p1–t21p1) ===================== */
.g6c-one{grid-template-columns:minmax(0,1fr)!important;max-width:640px;margin-left:auto;margin-right:auto}
.g6c-one .opt{text-align:left;font-family:var(--fb);font-size:16px;font-weight:600;line-height:1.35;padding:12px 14px}
