.g6c-piece.shake,.g6c-dial.bad{animation:g6cShake .35s}

/* ---- t15 forge ---- */
.g6c-forge{display:grid;grid-template-columns:110px minmax(0,1fr);gap:12px;align-items:center;background:linear-gradient(135deg,#0B2A5B,#1C3F7A);border-radius:18px;padding:12px;color:#fff;border:1.5px solid var(--bd)}
.g6c-rbox{position:relative;background:radial-gradient(circle at 50% 40%,#1D5FD1 0,#0B2A5B 70%);border-radius:14px;padding:6px}
.g6c-robot{width:100%;height:auto;display:block}
.g6c-rp>*{fill:#334E7E;stroke:#5B77A8;stroke-width:2;stroke-dasharray:4 3;transition:fill .4s,stroke .4s}
.g6c-rp line{stroke:#5B77A8}
.g6c-rp.lit>*{stroke:#fff;stroke-dasharray:0}
.g6c-rp[data-p=claim].lit>*{fill:#E3242B}
.g6c-rp[data-p=reason].lit>*{fill:#fff}
.g6c-rp[data-p=reason].lit .core{fill:#1D5FD1}
.g6c-rp[data-p=concession].lit>*{fill:#FFD43B}
.g6c-rp[data-p=conclusion].lit>*{fill:#E3242B}
.g6c-rp[data-p=claim].lit .eye{fill:#fff}
.g6c-rp[data-p=claim].lit .mouth{fill:#fff}
.g6c-forge.alive .eye{fill:#FFD43B!important;filter:drop-shadow(0 0 4px #FFD43B)}
.g6c-forge.alive .g6c-robot{animation:g6cBob 1s ease-in-out infinite}
@keyframes g6cBob{50%{transform:translateY(-4px) rotate(-2deg)}}
.g6c-spark{position:absolute;inset:0;pointer-events:none;border-radius:14px}
.g6c-spark.go{animation:g6cSpark .5s}
@keyframes g6cSpark{0%{box-shadow:inset 0 0 0 0 #FFD43B}50%{box-shadow:inset 0 0 30px 6px #FFD43B}100%{box-shadow:inset 0 0 0 0 transparent}}
.g6c-fq small{display:block;font-size:11px;letter-spacing:1.2px;color:#FFD6D8;font-weight:800}
.g6c-fq b{display:block;font-family:var(--fh);font-size:18px;line-height:1.25;margin:2px 0}
.g6c-fq i{display:block;font-size:13px;color:#C7D7F2}
.g6c-fq .g3-rep{margin:8px 0 0}
.g6c-steps{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}
.g6c-steps span{font-size:11px;font-weight:800;padding:3px 7px;border-radius:999px;background:rgba(255,255,255,.12);color:#C7D7F2}
.g6c-steps span.on{background:#FFD43B;color:var(--k)}
.g6c-steps span.done{background:#16A34A;color:#fff}
.g6c-para{margin:12px 0 4px;min-height:24px;line-height:1.55;font-size:16px}
.g6c-pp{animation:g6cPop .35s;padding:1px 3px;border-radius:5px;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.g6c-pp.claim{background:#FFE1E2}.g6c-pp.reason{background:#E2ECFF}.g6c-pp.concession{background:#FFF4C2}.g6c-pp.conclusion{background:#DCFCE7}
.g6c-slot{font-weight:700;margin:10px 0 6px;color:var(--k)}
.g6c-slot span{font-weight:600;color:var(--mut)}
.g6c-bank{display:grid;grid-template-columns:minmax(0,1fr);gap:8px}
.g6c-bank.off{display:none}
.g6c-piece{border:1.5px solid var(--bd);background:#fff;border-radius:14px;padding:10px 12px;text-align:left;font-size:15px;font-weight:600;color:var(--k);box-shadow:0 6px 18px rgba(11,42,91,.12);line-height:1.35;position:relative}
.g6c-piece::before{content:'🧩 '}
.g6c-piece:hover{background:var(--y3)}
.g6c-piece.used{display:none}
.g6c-piece.broken{opacity:.5;text-decoration:line-through;border-style:dashed;box-shadow:none}
.g6c-piece.broken::before{content:'🔧 '}
@media(min-width:761px){.g6c-forge{grid-template-columns:140px minmax(0,1fr)}.g6c-bank{grid-template-columns:1fr 1fr}}

/* ---- t16 duel ---- */
.g6c-arena{position:relative;display:grid;grid-template-columns:minmax(0,1fr) 40px minmax(0,1fr);align-items:center;gap:6px;background:linear-gradient(180deg,#0B2A5B 0,#1C3F7A 70%,#E3242B 70%,#E3242B 74%,#0B2A5B 74%);border-radius:18px;padding:12px;border:1.5px solid var(--bd);color:#fff;overflow:hidden}
.g6c-fighter{text-align:center}
.g6c-fighter b{display:block;font-family:var(--fh);font-size:15px}
.g6c-fighter small{font-weight:800;font-size:12px;color:#C7D7F2}
.g6c-av{font-size:44px;line-height:1.1;transition:transform .2s}
.g6c-fighter.foe .g6c-av{transform:scaleX(-1)}
.g6c-fighter.hit .g6c-av{animation:g6cHit .5s}
@keyframes g6cHit{0%,100%{transform:translateX(0)}20%{transform:translateX(-10px) rotate(-12deg)}50%{transform:translateX(8px) rotate(8deg);filter:brightness(2)}}
.g6c-hp{height:12px;background:rgba(255,255,255,.2);border-radius:999px;overflow:hidden;margin:4px 0 2px;border:2px solid #fff}
.g6c-hp i{display:block;height:100%;background:linear-gradient(90deg,#16A34A,#4ADE80);transition:width .6s}
.g6c-fighter.foe .g6c-hp i{background:linear-gradient(90deg,#E3242B,#FF7A7F);margin-left:auto}
.g6c-vs{font-family:var(--fh);font-weight:800;font-size:20px;color:#FFD43B;text-align:center;text-shadow:0 6px 16px rgba(227,36,43,.25)}
.g6c-pow{position:absolute;left:50%;top:40%;transform:translate(-50%,-50%);font-family:var(--fh);font-weight:800;font-size:28px;color:#FFD43B;text-shadow:0 6px 16px rgba(227,36,43,.25),-1px -1px 0 #0B2A5B;animation:g6cPop .45s;white-space:nowrap}
.g6c-pow.ouch{color:#fff;text-shadow:0 6px 18px rgba(11,42,91,.12)}
.g6c-claim{position:relative;margin:14px auto 4px;max-width:640px;background:#fff;border:1.5px solid var(--bd);border-radius:16px;padding:10px 14px;box-shadow:var(--sh)}
.g6c-claim::before{content:'';position:absolute;top:-12px;right:28%;border:10px solid transparent;border-bottom-color:var(--k);border-top:0}
.g6c-claim small{display:block;font-size:11px;letter-spacing:1px;font-weight:800;color:var(--y)}
.g6c-claim b{font-family:var(--fh);font-size:18px;line-height:1.3}
.g6c-timer{position:relative;height:16px;max-width:640px;margin:10px auto 0;background:#E2E8F0;border-radius:999px;overflow:hidden;border:1.5px solid var(--bd)}
.g6c-timer i{position:absolute;inset:0 auto 0 0;width:100%;background:linear-gradient(90deg,#FFD43B,#E3242B);transition:width .12s linear}
.g6c-timer span{position:relative;display:block;text-align:center;font-size:10px;font-weight:800;line-height:12px;color:var(--k)}
.g6c-timer.out span::after{content:' · agotado'}
.g6c-reb{display:block}
.g6c-ko{text-align:center;padding:20px 0}
.g6c-ko div{font-size:72px;animation:g6cPop .6s}
.g6c-ko b{display:block;font-family:var(--fh);font-size:24px;margin:6px 0}
.g6c-ko span{color:var(--mut);font-weight:700}

/* ---- t17 feed ---- */
.g6c-phone{max-width:330px;margin:0 auto;background:#0B2A5B;border-radius:30px;padding:10px 10px 14px;box-shadow:var(--sh2);position:relative}
.g6c-notch{width:90px;height:14px;background:#000;border-radius:0 0 12px 12px;margin:-10px auto 6px}
.g6c-app{display:flex;justify-content:space-between;align-items:center;color:#fff;padding:2px 8px 8px;font-family:var(--fh)}
.g6c-app b{font-size:18px;letter-spacing:.5px}
.g6c-post{position:relative;background:#fff;border-radius:18px;padding:12px;overflow:hidden;transition:background .3s}
.g6c-post.flagged{background:#FFF5F5}
.g6c-ph{display:flex;gap:8px;align-items:center}
.g6c-ph b{display:block;font-size:14px}
.g6c-ph small{color:var(--mut);font-size:12px}
.g6c-pav{width:38px;height:38px;border-radius:50%;background:var(--y3);display:grid;place-items:center;font-size:22px;border:1.5px solid var(--bd);flex:none}
.g6c-post p{margin:10px 0;font-size:16px;line-height:1.4}
.g6c-pact{display:flex;justify-content:space-between;font-size:13px;color:var(--mut);font-weight:700;border-top:1px solid #E2E8F0;padding-top:8px}
.g6c-stamp{position:absolute;top:42%;left:50%;transform:translate(-50%,-50%) rotate(-12deg);border:3px solid var(--y);color:var(--y);font-family:var(--fh);font-weight:800;font-size:17px;padding:4px 10px;border-radius:10px;background:rgba(255,255,255,.88);white-space:nowrap;animation:g6cStamp .35s}
@keyframes g6cStamp{0%{transform:translate(-50%,-50%) rotate(-12deg) scale(2.2);opacity:0}100%{transform:translate(-50%,-50%) rotate(-12deg) scale(1);opacity:1}}
.g6c-flags{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px auto 0;max-width:640px}
.g6c-flag{border:1.5px solid var(--bd);background:#fff;border-radius:14px;padding:9px 6px;box-shadow:0 6px 18px rgba(11,42,91,.12);color:var(--k);text-align:center}
.g6c-flag b{display:block;font-family:var(--fh);font-size:14px;line-height:1.2}
.g6c-flag small{display:block;font-size:12px;color:var(--mut);font-weight:600}
.g6c-flag.right{background:var(--ok2);border-color:var(--ok);box-shadow:2px 2px 0 var(--ok)}
.g6c-flag.wrong{background:var(--bad2);border-color:var(--bad);box-shadow:2px 2px 0 var(--bad)}
.g6c-guide{max-width:640px;margin:10px auto 0;font-size:14px;background:var(--y3);border-radius:12px;padding:8px 12px}
.g6c-guide summary{font-weight:800;cursor:pointer}
.g6c-guide p{margin:6px 0}
.g6c-fix{max-width:640px;margin:12px auto 0;border-left:5px solid var(--ok);background:#F0FDF4;border-radius:10px;padding:10px 12px}
.g6c-fix small{display:block;color:var(--mut);font-weight:600;margin-bottom:6px}
.g6c-fix p{margin:4px 0 0;font-style:italic}

/* ---- t18 nuance dial ---- */
.g6c-gbox{max-width:280px;margin:0 auto}
.g6c-gauge{width:100%;height:auto;display:block}
.g6c-glbl{display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:800;color:var(--mut);gap:6px}
.g6c-glbl b{font-family:var(--fh);color:var(--k);font-size:14px;text-align:center}
.g6c-nline{max-width:640px;margin:14px auto 4px;font-family:var(--fh);font-size:20px;line-height:1.9;text-align:center;font-weight:700;color:var(--k)}
.g6c-dial{display:inline;border:0;border-bottom:3px dashed var(--blue);background:var(--y3);color:var(--blue);font-family:var(--fh);font-size:20px;font-weight:800;padding:1px 6px;border-radius:4px 4px 0 0;margin:0 2px;line-height:1.5}
.g6c-dial i{font-style:normal;font-size:14px;margin-left:3px;opacity:.7}
.g6c-dial.abs{color:var(--y);border-bottom-color:var(--y);background:#FFF1F1}
.g6c-dial.spin{animation:g6cPop .3s}
.g6c-dial.ok{background:var(--ok2);color:#166534;border-bottom:3px solid var(--ok)}
.g6c-dial.bad{background:var(--bad2);color:#991B1B;border-bottom:3px solid var(--bad)}
.g6c-dial:disabled{cursor:default}
@media(max-width:520px){.g6c-nline,.g6c-dial{font-size:17px}}

/* ---- t19 red pen ---- */
.g6c-paper{position:relative;max-width:660px;margin:0 auto;background:#FFFEF7;border:1.5px solid var(--bd);border-radius:8px 8px 18px 8px;padding:14px 14px 14px 30px;box-shadow:var(--sh);background-image:repeating-linear-gradient(#FFFEF7 0 31px,#C9DBF5 31px 32px);line-height:32px}
.g6c-paper::before{content:'';position:absolute;top:0;bottom:0;left:18px;width:2px;background:#F2A0A3}
.g6c-ptitle{font-size:13px;color:var(--mut);font-weight:700;letter-spacing:.3px}
.g6c-ptitle b{color:var(--k)}
.g6c-sent{display:inline;border:0;background:transparent;font-size:16px;font-family:var(--fb);color:var(--k);padding:2px 1px;text-align:left;line-height:32px;border-radius:4px}
.g6c-sent:not(:disabled):hover{background:#FFF1B8}
.g6c-sent.struck{text-decoration:line-through;text-decoration-color:#E3242B;text-decoration-thickness:3px;color:#9AA6BA}
.g6c-sent.fine{background:#FFF4C2}
.g6c-sent:disabled{cursor:default}
.g6c-ins{color:#E3242B;font-style:italic;font-weight:700;animation:g6cPop .4s;display:inline}
.g6c-ins::before{content:' ✎ '}
.g6c-grade{position:absolute;top:-14px;right:-8px;width:52px;height:52px;border-radius:50%;border:2px solid #E3242B;color:#E3242B;font-family:var(--fh);font-weight:800;font-size:22px;display:grid;place-items:center;background:#fff;transform:rotate(12deg);line-height:1}
.g6c-grade:empty{display:none}
.g6c-why{max-width:640px;margin:10px auto 0;font-weight:700}
.g6c-why span{display:block;font-weight:600;color:var(--mut)}
.g6c-why.ok{color:#166534}.g6c-why.no{color:#991B1B}
.g6c-step2{font-weight:800;margin:12px auto 0;max-width:640px}

/* ---- t20 town hall ---- */
.g6c-hall{background:linear-gradient(180deg,#0B2A5B,#1C3F7A);border:1.5px solid var(--bd);border-radius:18px;padding:10px;color:#fff;position:relative;overflow:hidden}
.g6c-hbar{display:flex;justify-content:space-between;gap:6px;font-size:12px;font-weight:800;letter-spacing:.4px;flex-wrap:wrap}
.g6c-live{color:#FF6B70;animation:g6cBlink 1.2s infinite}
@keyframes g6cBlink{50%{opacity:.3}}
.g6c-crowd{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:8px;align-items:center;font-size:12px;font-weight:700;margin:8px 0}
.g6c-ap{height:10px;border-radius:999px;background:rgba(255,255,255,.2);overflow:hidden}
.g6c-ap i{display:block;height:100%;background:#FFD43B;transition:width .6s}
.g6c-seats{display:grid;gap:8px}
.g6c-seat{display:grid;grid-template-columns:44px minmax(0,1fr);gap:8px;align-items:center;text-align:left;background:rgba(255,255,255,.08);border:2px solid rgba(255,255,255,.25);border-radius:14px;padding:6px 8px;color:#fff}
.g6c-seat:not(:disabled):hover{background:rgba(255,255,255,.18)}
.g6c-sav{width:44px;height:44px;border-radius:50%;background:#fff;display:grid;place-items:center;font-size:26px;border:2px solid #FFD43B}
.g6c-sb{position:relative;background:#fff;color:var(--k);border-radius:12px;padding:6px 10px;font-size:15px;line-height:1.3}
.g6c-sb b{display:block;font-size:12px;color:var(--y);letter-spacing:.4px}
.g6c-seat.pick{border-color:#FFD43B;background:rgba(255,212,59,.25)}
.g6c-seat.pick .g6c-sb{box-shadow:0 0 0 3px #FFD43B}
.g6c-seat.wrong{opacity:.55}
.g6c-seat:disabled{cursor:default}
.g6c-podium{margin:10px auto 0;width:max-content;max-width:100%;background:#E3242B;border-radius:10px 10px 0 0;padding:6px 16px;font-size:14px;font-weight:700}
.g6c-react{position:absolute;right:10px;bottom:10px;font-size:26px;animation:g6cPop .5s}
.g6c-task{font-weight:800;margin:12px auto 0;max-width:640px}
.g6c-poll{max-width:420px;margin:10px auto;font-weight:700}
.g6c-poll p{font-family:var(--fh);font-size:18px;text-align:center}
.g6c-poll div{display:grid;grid-template-columns:70px minmax(0,1fr) 46px;gap:8px;align-items:center;margin:10px 0}
.g6c-poll i{display:block;height:22px;border-radius:8px;background:var(--k);width:var(--w);animation:g6cGrow 1s ease-out}
.g6c-poll i.n{background:var(--y)}
@keyframes g6cGrow{from{width:0}}

/* ---- t21 countdown ---- */
.g6c-pad{display:grid;grid-template-columns:96px minmax(0,1fr);gap:12px;align-items:center;background:radial-gradient(circle at 30% 20%,#1C3F7A,#06173A 75%);border:1.5px solid var(--bd);border-radius:18px;padding:10px;color:#fff;overflow:hidden}
.g6c-sky{background-image:radial-gradient(#fff 1px,transparent 1.5px);background-size:18px 18px;border-radius:12px;padding:4px 10px}
.g6c-rocket{width:100%;height:auto;display:block}
.g6c-rocket .flame,.g6c-rocket .flame2{opacity:.25;transform-origin:40px 108px}
.g6c-pad.fuel .g6c-rocket{animation:g6cRumble .5s}
.g6c-pad.fuel .flame,.g6c-pad.fuel .flame2{opacity:1;animation:g6cFlame .15s infinite alternate}
@keyframes g6cRumble{25%{transform:translateX(-2px)}50%{transform:translateX(2px) translateY(-3px)}75%{transform:translateX(-2px)}}
@keyframes g6cFlame{to{transform:scaleY(1.25)}}
.g6c-cd small{font-size:11px;letter-spacing:1.5px;color:#C7D7F2;font-weight:800}
.g6c-cd b{display:block;font-family:var(--fh);font-size:40px;line-height:1;color:#FFD43B;text-shadow:0 6px 16px rgba(227,36,43,.25)}
.g6c-cd span{font-weight:800;font-size:13px}
.g6c-fuel{display:flex;gap:4px;margin:8px 0 4px}
.g6c-fuel i{flex:1;height:14px;border-radius:4px;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.35)}
.g6c-fuel i.on{background:linear-gradient(180deg,#FFD43B,#E3242B);box-shadow:0 0 8px #FFD43B}
.g6c-src{max-width:640px;margin:12px auto 0;background:var(--y3);border-radius:14px;padding:10px 12px}
.g6c-src small{font-size:11px;letter-spacing:1px;font-weight:800;color:var(--mut)}
.g6c-src p{margin:2px 0 8px;font-size:16px;line-height:1.4}
.g6c-frame{font-family:var(--fh);font-weight:700;color:var(--k)}
.g6c-frame u{text-decoration:none;border-bottom:3px dashed var(--y);color:var(--y);padding:0 3px}
.g6c-frame u.ok{color:var(--ok);border-bottom-color:var(--ok)}
.g6c-frame u.fix{color:var(--blue);border-bottom-color:var(--blue)}
.g6c-inp{display:block;width:100%;max-width:640px;margin:10px auto 0;font-size:17px}
.g6c-chips{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;max-width:640px;margin:10px auto 0}
.g6c-chip{border:1.5px solid var(--bd);background:#fff;border-radius:999px;padding:7px 12px;font-weight:700;font-size:15px;color:var(--k);box-shadow:0 6px 18px rgba(11,42,91,.12)}
.g6c-chip.del{background:var(--y2)}
.g6c-chip:active{transform:translate(2px,2px);box-shadow:none}
.g6c-launch{position:relative;height:280px;border-radius:18px;background:linear-gradient(180deg,#06173A,#1C3F7A 80%,#E3242B 80%,#0B2A5B 84%);overflow:hidden;border:1.5px solid var(--bd);text-align:center}
.g6c-launch .g6c-stars{position:absolute;inset:0;background-image:radial-gradient(#fff 1px,transparent 1.5px);background-size:22px 22px;opacity:.6}
.g6c-launch .g6c-rocket{position:absolute;left:50%;bottom:16%;width:80px;margin-left:-40px}
.g6c-launch.go .g6c-rocket{animation:g6cLift 1.8s ease-in forwards}
.g6c-launch.go .flame,.g6c-launch.go .flame2{opacity:1;animation:g6cFlame .12s infinite alternate}
.g6c-launch.abort .g6c-rocket{animation:g6cRumble .4s 3;filter:grayscale(.6)}
@keyframes g6cLift{0%{transform:translateY(0)}15%{transform:translateY(4px)}100%{transform:translateY(-360px)}}
.g6c-launch b{position:absolute;left:0;right:0;top:14px;font-family:var(--fh);font-size:26px;color:#FFD43B;text-shadow:0 6px 16px rgba(227,36,43,.25)}
.g6c-launch.abort b{color:#fff;text-shadow:0 6px 16px rgba(227,36,43,.25)}
@media(min-width:761px){.g6c-pad{grid-template-columns:120px minmax(0,1fr)}}
/* END g6c */
/* BEGIN g5a */
/* ===== g5a — juegos únicos Módulo 3 (B1) temas 1–7 ===== */
.g5a-col{grid-template-columns:1fr!important}
.g5a-col .opt{font-size:16px;padding:11px 12px;line-height:1.3}
.g5a-q{text-align:center;font-weight:800;color:var(--k);margin:14px 0 2px;font-size:16px}
.g5a-mini{text-align:center;font-weight:700;margin:8px 0 0;font-size:15px}.g5a-mini.ok{color:#15803D}.g5a-mini.no{color:#B91C1C}
.g5a-call{display:flex;gap:10px;align-items:center;max-width:560px;margin:12px auto 4px;background:var(--k);color:#fff;border-radius:16px;padding:10px 14px;box-shadow:0 6px 16px rgba(227,36,43,.25)}
.g5a-call>span{font-size:30px;flex:none;animation:g5aRing 1.2s ease-in-out infinite}
.g5a-call small{display:block;opacity:.75;font-size:12px;font-weight:700;letter-spacing:.5px}
.g5a-call b{font-family:var(--fh);font-size:16px;line-height:1.3}
.g5a-qq>span{animation:none}
@keyframes g5aRing{0%,100%{transform:rotate(0)}10%,30%{transform:rotate(-14deg)}20%,40%{transform:rotate(14deg)}50%{transform:rotate(0)}}

/* t1p1 bola de cristal */
.g5a-zora{display:flex;gap:12px;align-items:center;max-width:560px;margin:0 auto;background:linear-gradient(135deg,#1E1B4B,#0B2A5B);border-radius:18px;padding:12px;color:#fff;border:1.5px solid var(--bd)}
.g5a-ball{position:relative;flex:none;width:96px;height:96px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff 0 6%,#C4B5FD 14%,#7C3AED 48%,#312E81 80%);box-shadow:0 0 24px #A78BFA,inset -8px -10px 18px rgba(0,0,0,.35);display:grid;place-items:center;overflow:hidden}
.g5a-ball i{position:absolute;inset:-20%;background:conic-gradient(from 0deg,transparent,rgba(255,255,255,.35),transparent 40%,rgba(236,72,153,.35),transparent 70%);animation:g5aSpin 3.5s linear infinite}
.g5a-ball span{position:relative;font-size:44px;animation:g5aAppear 1.6s ease-out both}
.g5a-ball::after{content:"";position:absolute;left:18%;right:18%;bottom:-6px;height:14px;border-radius:50%;background:#A16207}
.g5a-ctx{font-weight:700;font-size:15px;line-height:1.35}.g5a-ctx small{display:block;color:#FDE68A;font-size:12px;letter-spacing:.5px;margin-bottom:3px}
@keyframes g5aSpin{to{transform:rotate(360deg)}}
@keyframes g5aAppear{0%{opacity:0;filter:blur(8px);transform:scale(.4)}100%{opacity:1;filter:none;transform:none}}

/* t1p2 agenda */
.g5a-cal{max-width:560px;margin:0 auto;background:#fff;border:1.5px solid var(--bd);border-radius:16px;overflow:hidden}
.g5a-day{display:flex;gap:8px;align-items:stretch;border-bottom:2px solid #E2E8F0;padding:6px 8px}
.g5a-day:last-child{border-bottom:0}
.g5a-day>b{flex:none;width:52px;font-family:var(--fh);color:var(--k);font-size:16px;line-height:1.1}.g5a-day>b small{display:block;font-size:10px;color:#64748B;font-family:var(--fb)}
.g5a-day>div{display:flex;flex-wrap:wrap;gap:5px;min-width:0;flex:1}
.g5a-day span{background:var(--y3);border-radius:8px;padding:3px 7px;font-size:13px;font-weight:700;color:var(--k);max-width:100%}
.g5a-day span i{font-style:normal;color:var(--y);font-weight:800;font-size:12px}
.g5a-day span.dim{opacity:.55}
.g5a-day.hl{background:#FFFBEB}
.g5a-day span.on{background:var(--k);color:#fff}.g5a-day span.on i{color:#FDE68A}
.g5a-day span.free{background:#DCFCE7;color:#166534;border:2px dashed #16A34A}
.g5a-day span.blink{animation:g5aBlink 1s ease-in-out 3}
@keyframes g5aBlink{50%{transform:scale(1.06);box-shadow:0 0 0 4px #FACC15}}

/* t2p1 detector */
.g5a-mach{max-width:520px;margin:0 auto;background:#1F2937;border:1.5px solid var(--bd);border-radius:20px;padding:10px;box-shadow:0 6px 16px rgba(227,36,43,.25)}
.g5a-mh{display:flex;justify-content:space-between;align-items:center;color:#A7F3D0;font-family:monospace;font-weight:900;font-size:13px;letter-spacing:1.5px;margin-bottom:8px}
.g5a-led{width:14px;height:14px;border-radius:50%;background:#EF4444;box-shadow:0 0 10px #EF4444;animation:g5aBlink 1s infinite}.g5a-led.ok{background:#22C55E;box-shadow:0 0 10px #22C55E;animation:none}
.g5a-scr{position:relative;background:#0F172A;border-radius:12px;padding:8px 12px;margin-bottom:8px;color:#E2E8F0;overflow:hidden}
.g5a-scr small{display:block;font-size:11px;color:#94A3B8;font-weight:700;letter-spacing:1px}
.g5a-scr p{margin:2px 0 0;font-family:var(--fh);font-weight:700;font-size:18px;line-height:1.3}
.g5a-scr.bad{border:2px solid #EF4444}.g5a-scr.good{border:2px solid #22C55E;background:#052E16}
.g5a-scr mark{background:#EF4444;color:#fff;border-radius:5px;padding:0 4px}
.g5a-laser{position:absolute;top:0;bottom:0;width:3px;background:#F87171;box-shadow:0 0 10px #F87171;animation:g5aScan 1.6s ease-in-out infinite alternate}
@keyframes g5aScan{from{left:0}to{left:calc(100% - 3px)}}

/* t2p2 laboratorio */
.g5a-lab{max-width:520px;margin:0 auto;text-align:center}
.g5a-ctxes{display:flex;gap:10px;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:var(--k);margin-bottom:10px}.g5a-ctxes span{font-size:36px}
.g5a-beaker{position:relative;margin:0 auto;max-width:320px;min-height:96px;border:1.5px solid var(--bd);border-top:0;border-radius:0 0 30px 30px;background:#F8FAFC;display:grid;place-items:center;padding:16px 10px;overflow:hidden}
.g5a-beaker b{position:relative;font-family:var(--fh);font-size:21px;color:var(--k);z-index:1}
.g5a-beaker b u{color:#7C3AED;text-decoration:none;border-bottom:3px dashed #7C3AED}
.g5a-liq{position:absolute;left:0;right:0;bottom:0;height:22%;background:#BFDBFE;transition:height .6s,background .6s}
.g5a-beaker.ok .g5a-liq{height:100%;background:#BBF7D0}
.g5a-beaker.no .g5a-liq{height:100%;background:#FECACA}
.g5a-beaker.ok::after{content:"🫧 🫧 🫧";position:absolute;top:4px;left:0;right:0;font-size:16px;animation:g5aUp 1s ease-out}
.g5a-beaker.no::after{content:"💨";position:absolute;top:0;right:10px;font-size:26px;animation:g5aUp 1s ease-out}
@keyframes g5aUp{from{transform:translateY(40px);opacity:0}to{transform:none;opacity:1}}
.g5a-rack{display:flex;gap:10px;justify-content:center;margin-top:14px;flex-wrap:wrap}
.g5a-tube{flex:1 1 90px;max-width:160px;min-width:0;display:flex;flex-direction:column;align-items:center;gap:6px;background:#fff;border:1.5px solid var(--bd);border-radius:14px;padding:8px 6px;box-shadow:0 6px 18px rgba(11,42,91,.12);font-family:var(--fh);font-weight:800;color:var(--k);font-size:15px}
.g5a-tube i{width:22px;height:46px;border:1.5px solid var(--bd);border-top:0;border-radius:0 0 12px 12px;background:linear-gradient(transparent 40%,var(--c) 40%)}
.g5a-tube span{word-break:break-word;line-height:1.2}
.g5a-tube.right{background:var(--ok2,#DCFCE7);border-color:#16A34A}.g5a-tube.wrong{background:#FEE2E2;border-color:#DC2626;animation:shake .35s}

/* t3p1 objetos perdidos */
.g5a-item{display:flex;gap:12px;align-items:center;max-width:420px;margin:0 auto 10px;background:#FFFBEB;border:3px dashed #B45309;border-radius:16px;padding:10px 14px}
.g5a-item>span{font-size:44px}.g5a-item small{display:block;font-size:11px;letter-spacing:2px;font-weight:800;color:#B45309}.g5a-item b{font-family:var(--fh);font-size:18px;color:var(--k)}
.g5a-clues{max-width:520px;margin:0 auto;display:flex;flex-direction:column;gap:6px}
.g5a-bub{display:flex;gap:8px;align-items:flex-start;animation:pop .3s}
.g5a-bub>span{font-size:28px;flex:none}
.g5a-bub p{margin:0;background:#fff;border:1.5px solid var(--bd);border-radius:4px 14px 14px 14px;padding:6px 10px;font-weight:700;font-size:15px}
.g5a-bub small{display:block;font-size:11px;color:var(--y);font-weight:800}
.g5a-guests{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-width:480px;margin:8px auto 0}
.g5a-guests button{background:#fff;border:1.5px solid var(--bd);border-radius:14px;padding:8px 4px;box-shadow:0 6px 18px rgba(11,42,91,.12);display:flex;flex-direction:column;align-items:center;gap:2px;min-width:0;color:var(--k)}
.g5a-guests span{font-size:34px;line-height:1.1}.g5a-guests b{font-family:var(--fh);font-size:13px;line-height:1.15}.g5a-guests small{font-size:11px;color:#64748B}
.g5a-guests button.right{background:#DCFCE7;border-color:#16A34A}.g5a-guests button.wrong{background:#FEE2E2;border-color:#DC2626;animation:shake .35s}

/* t3p2 tribunal */
.g5a-court{max-width:540px;margin:0 auto;background:linear-gradient(#7C2D12,#451A03);border:1.5px solid var(--bd);border-radius:18px;padding:10px;color:#fff}
.g5a-bench{display:flex;align-items:center;justify-content:center;gap:8px;font-family:var(--fh);font-size:14px;letter-spacing:1px;margin-bottom:8px}
.g5a-gavel{font-size:28px;display:inline-block;transform-origin:80% 80%}.g5a-gavel.bang{animation:g5aBang .45s}
@keyframes g5aBang{40%{transform:rotate(-40deg)}70%{transform:rotate(10deg)}}
.g5a-wit{display:flex;gap:8px;align-items:flex-start;background:#FEF3C7;color:var(--k);border-radius:12px;padding:8px 10px}
.g5a-wit>span{font-size:30px}.g5a-wit p{margin:0;font-family:var(--fh);font-weight:800;font-size:18px;line-height:1.3}.g5a-wit small{display:block;font-family:var(--fb);font-size:11px;color:#92400E}
.g5a-jury{display:flex;align-items:center;gap:8px;margin-top:8px;font-size:12px;font-weight:800}.g5a-jury small{flex:none}
.g5a-jury i{display:block;height:8px;border-radius:4px;background:#FACC15;transition:width .6s;min-width:4px}
.g5a-verd .opt small{display:block;font-size:12px;font-weight:600;color:#64748B}

/* t4p1 bucket list */
.g5a-note{max-width:520px;margin:0 auto;background:#FFFDF5;border:1.5px solid var(--bd);border-radius:14px;padding:8px 10px 6px 26px;background-image:linear-gradient(90deg,transparent 18px,#FCA5A5 18px,#FCA5A5 20px,transparent 20px);box-shadow:0 6px 18px rgba(11,42,91,.12)}
.g5a-nh{font-family:var(--fh);font-weight:800;color:var(--k);font-size:16px;margin-bottom:4px}.g5a-nh small{font-size:12px;color:#64748B;font-weight:600;margin-left:4px}
.g5a-li{display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:4px 6px;border-bottom:1px dashed #CBD5E1;border-radius:8px;position:relative}
.g5a-li>span{font-size:20px}.g5a-li b{font-size:14px;color:var(--k);flex:1;min-width:120px}
.g5a-li em{font-style:normal;font-size:12px;font-weight:800;padding:1px 7px;border-radius:999px}
.g5a-li em.done{background:#DCFCE7;color:#166534}.g5a-li em.yet{background:#FEF3C7;color:#92400E}.g5a-li em.never{background:#FEE2E2;color:#991B1B}
.g5a-li.hl{background:#FEF9C3;outline:3px solid #FACC15}
.g5a-li.st::after{content:"⭐";position:absolute;right:-8px;top:-6px;font-size:16px}

/* t4p2 CV */
.g5a-cv{max-width:560px;margin:0 auto;background:#fff;border:1.5px solid var(--bd);border-radius:14px;padding:6px}
.g5a-tl{width:100%;height:auto;display:block}
.g5a-tl g.hl text{fill:#B91C1C}

/* t5p1 llegaste tarde */
.g5a-scene{display:flex;align-items:center;justify-content:center;gap:8px;font-family:var(--fh);color:var(--k);font-size:17px;margin-bottom:8px}.g5a-scene span{font-size:34px}
.g5a-vt{max-width:420px;margin:0 auto;position:relative;padding-left:22px}
.g5a-vt::before{content:"";position:absolute;left:9px;top:6px;bottom:6px;width:4px;border-radius:2px;background:var(--k)}
.g5a-vt>div{position:relative;display:flex;gap:10px;align-items:center;background:#fff;border:1.5px solid var(--bd);border-radius:12px;padding:6px 10px;margin-bottom:6px;animation:g5aSlide .4s both}
.g5a-vt>div::before{content:"";position:absolute;left:-19px;width:12px;height:12px;border-radius:50%;background:#fff;border:1.5px solid var(--bd)}
.g5a-vt i{font-style:normal;font-family:var(--fh);font-weight:800;color:var(--y);flex:none;width:44px}
.g5a-vt b{font-size:15px;color:var(--k)}
.g5a-vt>div.before{background:#E0E7FF}.g5a-vt>div.after{background:#F1F5F9;opacity:.75}
.g5a-vt>div.you{background:var(--y);border-color:var(--y)}.g5a-vt>div.you b,.g5a-vt>div.you i{color:#fff}.g5a-vt>div.you::before{background:var(--y);border-color:#fff}
@keyframes g5aSlide{from{opacity:0;transform:translateX(-20px)}to{opacity:1;transform:none}}

/* t5p2 noir */
.g5a-noir{max-width:560px;margin:0 auto;background:#111827;border:3px solid #000;border-radius:14px;padding:8px;box-shadow:0 6px 16px rgba(227,36,43,.25)}
.g5a-nh2{color:#FDE68A;font-family:monospace;font-weight:900;font-size:13px;letter-spacing:1px;margin-bottom:6px}.g5a-nh2 span{color:#fff}
.g5a-paper{background:#FEF9E7;border-radius:6px;padding:8px 12px;max-height:150px;overflow-y:auto;font-family:'Courier New',monospace;color:#1F2937;font-size:14px;line-height:1.4}
.g5a-paper p{margin:0 0 5px;animation:g5aType .6s steps(20) both}.g5a-paper p.mut{color:#9CA3AF}
@keyframes g5aType{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}
.g5a-type{font-family:'Courier New',monospace!important}
.g5a-clue{max-width:560px;margin:12px auto 4px;background:#FEF3C7;border:2px solid #B45309;border-radius:12px;padding:10px 12px;font-weight:700;font-size:15px;color:#78350F}
.g5a-sus button{background:#1F2937;color:#fff;border-color:#000}.g5a-sus small{color:#FDE68A}

/* t6p1 pirámide */
.g5a-card{background:#fff;border:1.5px solid var(--bd);border-radius:14px;padding:10px 12px;box-shadow:0 6px 18px rgba(11,42,91,.12)}
.g5a-pyr{display:flex;flex-direction:column;align-items:center;gap:6px;margin:14px auto 0;max-width:340px}
.g5a-pyr button{border:1.5px solid var(--bd);border-radius:12px;color:#fff;font-family:var(--fh);padding:6px 8px;box-shadow:0 6px 18px rgba(11,42,91,.12);display:flex;flex-direction:column;align-items:center;line-height:1.15;max-width:100%}
.g5a-pyr b{font-size:20px}.g5a-pyr small{font-size:11px;font-weight:600;opacity:.9}
.g5a-pyr .l1{width:46%;background:#E3242B}.g5a-pyr .l2{width:72%;background:#1D5FD1}.g5a-pyr .l3{width:100%;background:#0B2A5B}
.g5a-pyr .l0{width:46%;background:#fff;color:var(--k);margin-top:6px;border-style:dashed}
.g5a-pyr button.right,.g5a-bu button.right{outline:4px solid #22C55E;outline-offset:2px;animation:pop .4s}
.g5a-pyr button.wrong,.g5a-bu button.wrong{outline:4px solid #DC2626;outline-offset:2px;animation:shake .35s}
.g5a-bu{display:grid;grid-template-columns:1fr 1fr;gap:10px;max-width:420px;margin:14px auto 0}
.g5a-bu button{background:#fff;border:1.5px solid var(--bd);border-radius:14px;padding:10px 6px;box-shadow:0 6px 18px rgba(11,42,91,.12);display:flex;flex-direction:column;align-items:center;gap:6px;color:var(--k)}
.g5a-bu b{font-family:var(--fh);font-size:19px}.g5a-bu small{font-size:12px;font-weight:600;color:#64748B}
.g5a-bu i{display:block;width:80%;height:10px;border-radius:5px;background:#E2E8F0;position:relative}
.g5a-bu i.flag::after{content:"🏁";position:absolute;right:-6px;top:-14px;font-size:18px;font-style:normal}
.g5a-bu i.bar{background:linear-gradient(90deg,var(--y),var(--y) 100%)}

/* t6p2 pódcast */
.g5a-pod{display:flex;gap:10px;max-width:520px;margin:0 auto;background:#18181B;border-radius:18px;padding:10px;color:#fff;border:1.5px solid var(--bd)}
.g5a-cover{flex:none;width:78px;height:78px;border-radius:12px;background:linear-gradient(135deg,#E3242B,#7C3AED);display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:var(--fh);font-size:9px;font-weight:900;line-height:1.05;text-align:center;letter-spacing:1px}
.g5a-cover b{font-size:26px}
.g5a-pr{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:space-between}
.g5a-pr small{font-size:11px;color:#A1A1AA;font-weight:700}
.g5a-wave{display:flex;align-items:center;gap:2px;height:38px}
.g5a-wave i{flex:1;height:var(--h);background:#22C55E;border-radius:2px;animation:g5aWave .8s ease-in-out infinite alternate;animation-delay:var(--d)}
@keyframes g5aWave{from{transform:scaleY(.35)}to{transform:scaleY(1)}}
.g5a-prog{height:5px;background:#3F3F46;border-radius:3px;overflow:hidden}.g5a-prog i{display:block;height:100%;background:#E3242B}
.g5a-tr{display:flex;gap:8px;align-items:flex-start;max-width:520px;margin:12px auto 0}
.g5a-tr>span{font-size:30px;flex:none}
.g5a-tr p{margin:0;background:#fff;border:1.5px solid var(--bd);border-radius:4px 16px 16px 16px;padding:8px 12px;font-family:var(--fh);font-weight:700;font-size:17px;line-height:1.35;color:var(--k)}
.g5a-tr small{display:block;font-family:var(--fb);font-size:11px;color:var(--y);font-weight:800}
.g5a-tr mark.bleep{background:#18181B;color:#FACC15;border-radius:6px;padding:0 6px;font-size:13px;letter-spacing:1px;animation:g5aBlink 1s infinite}

/* t7p1 dron */
.g5a-mapbox{position:relative;max-width:480px;margin:0 auto;aspect-ratio:320/220;border:1.5px solid var(--bd);border-radius:16px;overflow:hidden;box-shadow:0 6px 18px rgba(11,42,91,.12)}
.g5a-map{position:absolute;inset:0;width:100%;height:100%}
.g5a-pin{position:absolute;transform:translate(-50%,-50%);font-size:clamp(18px,5.5vw,26px);pointer-events:none}
.g5a-drone{position:absolute;transform:translate(-50%,-50%);width:38px;height:38px;filter:drop-shadow(2px 4px 2px rgba(0,0,0,.35));transition:opacity .4s;z-index:2}
.g5a-rot circle{animation:g5aFlick .15s linear infinite}
@keyframes g5aFlick{50%{opacity:.4}}

/* t7p2 ciudad */
.g5a-city{position:relative;display:grid;grid-template-columns:1fr 1fr 24px 1fr 1fr;grid-template-rows:1fr 22px 1fr 22px 1fr;max-width:460px;margin:0 auto;aspect-ratio:1.25;background:#D9F99D;border:1.5px solid var(--bd);border-radius:14px;overflow:hidden;gap:0}
.g5a-st{grid-column:1/-1;background:#475569;display:flex;align-items:center;justify-content:flex-start;padding-left:6px;z-index:0}
.g5a-st span,.g5a-av span{color:#fff;font-size:10px;font-weight:800;letter-spacing:.5px;white-space:nowrap}
.g5a-av{grid-row:1/-1;grid-column:3;background:#475569;display:flex;align-items:center;justify-content:center;z-index:1}
.g5a-av span{writing-mode:vertical-rl;transform:rotate(180deg)}
.g5a-lot{margin:4px;border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;overflow:hidden;z-index:2;line-height:1.05}
.g5a-lot span{font-size:clamp(18px,6vw,28px)}.g5a-lot small{font-size:9.5px;font-weight:800;color:var(--k);text-align:center}
.g5a-lot.fix{background:#fff;border:1.5px solid var(--bd)}
button.g5a-lot{background:#FEF9C3;border:3px dashed var(--k);color:var(--k);padding:0}
button.g5a-lot.right{background:#BBF7D0;border-style:solid;border-color:#16A34A;animation:pop .4s}
button.g5a-lot.wrong{background:#FECACA;border-color:#DC2626;animation:shake .35s}
.g5a-n{position:absolute;right:4px;top:2px;font-style:normal;font-size:10px;font-weight:900;color:var(--k);z-index:3;background:#fff;border-radius:6px;padding:0 4px}
@media(max-width:380px){.g5a-zora{flex-direction:column;text-align:center}.g5a-ball{width:84px;height:84px}}
/* END g5a */
/* BEGIN g6b */
/* ===== Juegos únicos Módulo 4 · temas 8–14 (g6b) ===== */
.g6b-col{grid-template-columns:1fr!important;max-width:640px;margin-left:auto;margin-right:auto}
.g6b-col .opt{text-align:left;font-size:16.5px;line-height:1.3;padding:12px 14px}
.g6b-step{font-family:var(--fh);font-weight:800;margin:14px 0 0;color:var(--k);font-size:16px;text-align:center}
.g6b-step i{font-weight:600;color:#64748B}
/* t8p1 ping-pong */
.g6b-pong{max-width:560px;margin:0 auto}
.g6b-score{display:flex;justify-content:space-between;align-items:center;font-family:var(--fh);font-weight:800;font-size:15px;margin-bottom:6px}
.g6b-score b{display:inline-block;min-width:30px;text-align:center;background:var(--k);color:#fff;border-radius:8px;padding:2px 6px;font-size:18px}
.g6b-vs{color:var(--y);font-size:13px}
.g6b-table{position:relative;height:120px;border:1.5px solid var(--bd);border-radius:14px;background:linear-gradient(#1D5FD1,#174ea9);overflow:hidden;box-shadow:var(--sh)}
.g6b-table:before{content:"";position:absolute;left:4%;right:4%;top:50%;border-top:2px solid rgba(255,255,255,.7)}
.g6b-net{position:absolute;left:50%;top:0;bottom:0;width:4px;margin-left:-2px;background:repeating-linear-gradient(#fff 0 6px,#cbd5e1 6px 10px)}
.g6b-paddle{position:absolute;top:50%;transform:translateY(-50%);font-size:34px}
