@keyframes g6bTime{to{transform:scaleX(0)}}
/* t8p2 pitch analyzer */
.g6b-scope{max-width:560px;margin:0 auto 8px;border:1.5px solid var(--bd);border-radius:14px;background:#06142e;overflow:hidden;box-shadow:var(--sh)}
