.g6b-scope svg{display:block;width:100%;height:90px}
.g6b-scope .grid{stroke:rgba(125,211,252,.18);stroke-width:1;fill:none}
.g6b-scope .wave{fill:none;stroke:#22d3ee;stroke-width:3;stroke-linecap:round}
