.g6b-q .g3-rep{margin:4px 0 0}
/* t10p1 concierge */
.g6b-hotel{max-width:560px;margin:0 auto;border:1.5px solid var(--bd);border-radius:16px;background:linear-gradient(#FFF7ED,#fff);padding:8px 10px;box-shadow:var(--sh)}
.g6b-hotel-top{display:flex;justify-content:space-between;gap:6px;flex-wrap:wrap;font:800 11px var(--fh);letter-spacing:.5px}
