.g6b-prob{max-width:560px;margin:0 auto 8px;background:#FFFBEB;border:1.5px solid var(--bd);border-radius:14px;padding:10px 12px;font-weight:700;font-size:16px;text-align:center}
.g6b-map{position:relative;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px 10px;max-width:560px;margin:0 auto;padding:12px;border:1.5px solid var(--bd);border-radius:16px;background:#bbf7d0;box-shadow:var(--sh);overflow:hidden}
