/* t13p1 timeline radar */
.g6b-radar{max-width:600px;margin:0 auto;border:1.5px solid var(--bd);border-radius:16px;background:#06142e;color:#e0f2fe;padding:8px 10px 10px;box-shadow:var(--sh)}
