.g6b-dl{text-align:center;font:800 14px var(--fh);color:#fff;background:var(--y);border-radius:10px;padding:5px;max-width:300px;margin:0 auto 8px;animation:g6bPulse .9s infinite alternate}
.g6b-card{display:flex;gap:10px;align-items:center;max-width:420px;margin:0 auto 10px;background:#FEF9C3;border:1.5px solid var(--bd);border-radius:10px;padding:8px 10px;box-shadow:var(--sh);transform:rotate(-1.5deg)}
