.g6b-odo{display:flex;flex-direction:column;align-items:center;margin:4px auto}
.g6b-odo-w{display:flex;gap:4px;padding:6px;background:#111827;border-radius:12px;border:1.5px solid var(--bd);box-shadow:var(--sh)}
