.g6b-levers small{font:600 13px var(--fb);color:#475569;margin-top:2px}
@media(max-width:420px){.g6b-pitchbtns .opt{font-size:24px}.g6b-dig{width:34px;height:48px}.g6b-dig b{height:48px;font-size:28px}.g6b-map{gap:20px 6px;padding:10px 8px}.g6b-shop span{font-size:22px}.g6b-shop small{font-size:9.5px}.g6b-legend{font-size:12.5px}.g6b-stn{font-size:11px}.g6b-stn small{font-size:9px}}
/* END g6b */
/* BEGIN g6a */
/* ===== g6a — juegos Módulo 4 (B2+) temas 1–7 ===== */
.opts.g6a-col{grid-template-columns:1fr!important;max-width:640px;margin-left:auto;margin-right:auto}
.opts.g6a-col .opt{font-size:16.5px;text-align:left;padding:12px 14px;line-height:1.3}
