.g6a-blank{display:inline-block;min-width:44px;border-bottom:3px dashed var(--y);text-decoration:none;color:var(--y);font-weight:800;padding:0 4px;text-align:center}
.g6a-blank.on{border-bottom-style:solid;color:#0B7A3B;border-color:#2E9E5B;background:#E7F8EE;border-radius:3px 3px 0 0}
/* domino */
.g6a-dm-top{display:flex;align-items:center;justify-content:center;gap:8px;font-family:var(--fh);color:var(--k);margin:0 0 8px}
.g6a-dm-top span{font-size:26px}
.g6a-dm-row{display:flex;justify-content:center;align-items:flex-end;gap:10px;padding:12px 6px 8px;margin:0 auto 10px;max-width:420px;background:linear-gradient(#fff0,#fff0 85%,#e3e8f0 85%);border-radius:12px}
.g6a-dm-tile{width:42px;height:74px;border-radius:9px;background:#fff;border:1.5px solid var(--bd);display:flex;flex-direction:column;align-items:center;justify-content:space-around;box-shadow:0 6px 18px rgba(11,42,91,.12);transform-origin:bottom right;transition:transform .5s cubic-bezier(.5,0,.75,0) var(--d)}
.g6a-dm-tile i{width:9px;height:9px;border-radius:50%;background:var(--k)}
.g6a-dm-tile b{font-family:var(--fh);font-size:15px;color:var(--k)}
.g6a-dm-tile.now{background:#FFF6D6;border-color:var(--y);box-shadow:0 6px 16px rgba(227,36,43,.25);animation:g6awob 1.2s infinite}
.g6a-dm-tile.ok{background:#E7F8EE}.g6a-dm-tile.ok b{color:#0B7A3B}
.g6a-dm-tile.bad{background:#FDE7E8}.g6a-dm-tile.bad b{color:var(--y)}
.g6a-dm-goal{font-size:28px;align-self:center}
.g6a-dm-row.fall .g6a-dm-tile{transform:rotate(68deg)}
@keyframes g6awob{0%,100%{transform:rotate(-3deg)}50%{transform:rotate(3deg)}}
.g6a-dm-card{max-width:640px;margin:0 auto 6px;background:var(--k);color:#fff;border-radius:16px;padding:12px 16px;text-align:center}
