.g6a-dm-card p{margin:0;font-family:var(--fh);font-size:20px;line-height:1.35}
.g6a-dm-card .g6a-blank{color:#FFD43B;border-color:#FFD43B}
.g6a-dm-card .g6a-blank.on{background:#2E9E5B;color:#fff;border-color:#fff}
.g6a-dm-list{max-width:620px;margin:6px auto;padding-left:22px;line-height:1.45;font-weight:600}
.g6a-dm-list li{margin:4px 0}.g6a-dm-list li.ok::marker{color:#2E9E5B}.g6a-dm-list li.no{color:#9b1c22}
/* negotiation */
.g6a-ng-hud{display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap;margin-bottom:8px}
.g6a-ng-g{text-align:center;width:170px}.g6a-ng-g small{display:block;font-size:12px;color:var(--mut);font-weight:700;margin-top:-4px}
.g6a-ng-gauge{width:170px;height:auto;display:block}
