.g6a-ng-bub{position:relative;max-width:560px;margin:4px auto 8px;background:#EAF2FD;border:1.5px solid var(--bd);border-radius:18px;padding:12px 14px;font-family:var(--fh);font-size:18px;color:var(--k);text-align:center}
