@keyframes g6aglitch{0%{transform:translateX(0)}20%{transform:translateX(-6px) skewX(8deg)}40%{transform:translateX(5px)}60%{transform:translateX(-3px) skewX(-6deg)}100%{transform:none}}
@keyframes g6ablink{50%{opacity:0}}
