.opts.g6a-3{grid-template-columns:repeat(3,minmax(0,1fr))!important;max-width:560px;margin-left:auto;margin-right:auto}
.opts.g6a-3 .opt{font-size:16px;padding:12px 6px}
/* post-mortem */
.g6a-pm-hud{text-align:center;font-weight:700;margin-bottom:6px}
.g6a-pm-board{max-width:560px;margin:0 auto 10px;background:#c8a574 radial-gradient(#b8915c 1px,transparent 1.5px) 0 0/10px 10px;border:8px solid #7a5230;border-radius:12px;padding:10px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
