.g6a-sw-ph{height:150px;background:linear-gradient(135deg,#E3242B,#8B5CF6 55%,#1D5FD1);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center}
.g6a-sw-ph span{font-size:60px;line-height:1}.g6a-sw-ph b{font-family:var(--fh);font-size:19px}.g6a-sw-ph small{font-size:13px;opacity:.9}
