.g6a-mm-who{display:flex;align-items:center;gap:10px;max-width:520px;margin:0 auto 4px;flex-wrap:wrap;justify-content:center}
.g6a-mm-av{font-size:46px}
.g6a-mm-bub{flex:1;min-width:180px;background:#EAF2FD;border:1.5px solid var(--bd);border-radius:18px 18px 18px 4px;padding:8px 12px;font-family:var(--fh);font-size:18px;color:var(--k)}
.g6a-mm-bub small{display:block;font-size:12px;color:var(--mut)}
.g6a-mm-cards{display:flex;flex-wrap:wrap;gap:10px;justify-content:center}
.g6a-mm-card{width:140px;background:#fff;border:1.5px solid var(--bd);border-radius:12px;padding:8px;text-align:center;box-shadow:0 6px 18px rgba(11,42,91,.12)}
.g6a-mm-card span{font-size:36px;display:block}.g6a-mm-card small{display:block;font-size:12.5px;color:var(--mut)}
/* radar */
.g6a-rd{position:relative;width:min(300px,100%);aspect-ratio:1;margin:8px auto;border-radius:50%;background:radial-gradient(#0f3d26,#06210f);border:3px solid #1a5c38;overflow:hidden;opacity:.55}
.g6a-rd.act{opacity:1}
.g6a-rd-ring{position:absolute;border:1px solid rgba(70,255,140,.35);border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%)}
.g6a-rd-ring.r1{width:45%;height:45%}.g6a-rd-ring.r2{width:75%;height:75%}
.g6a-rd-sweep{position:absolute;inset:0;border-radius:50%;background:conic-gradient(rgba(70,255,140,.45),rgba(70,255,140,0) 25%);animation:g6aspin 3s linear infinite}
.g6a-rd-b{position:absolute;transform:translate(-50%,-50%);background:#08321b;color:#7CFFB0;border:2px solid #46ff8c;border-radius:999px;font-family:monospace;font-weight:800;font-size:13px;padding:4px 7px;cursor:pointer;z-index:2}
.g6a-rd-b:not(:disabled):hover{background:#46ff8c;color:#06210f}
.g6a-rd-b.right{background:#46ff8c;color:#06210f;box-shadow:0 0 12px #46ff8c}
.g6a-rd-b.wrong{background:#E3242B;color:#fff;border-color:#fff}
.g6a-rd-c{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:24px}
.g6a-rd-tx{max-width:560px;margin:0 auto 6px;background:#06210f;color:#c9ffe0;border-radius:12px;padding:10px 14px;font-family:monospace;text-align:center}
.g6a-rd-tx small{display:block;color:#46ff8c;letter-spacing:1px;font-size:11px}
.g6a-rd-tx p{margin:6px 0 0;font-size:17px;line-height:1.5;font-family:var(--fh)}
.g6a-rd-tx p small{display:inline;color:#9fd8b8;font-size:13px;letter-spacing:0}
.g6a-rd-tx .g6a-blank{color:#FFD43B;border-color:#FFD43B}
.g6a-rd-tx .g3-rep{margin-top:6px}
/* sherlock */
.g6a-sh-file{display:flex;align-items:center;gap:10px;max-width:520px;margin:0 auto 8px;background:#f3e9d2;border:2px solid #b89b62;border-radius:6px 16px 6px 6px;padding:8px 12px;font-family:Georgia,serif}
.g6a-sh-av{font-size:40px}.g6a-sh-file small{display:block;font-size:11px;letter-spacing:1px;color:#7a5230}.g6a-sh-file b{font-size:20px;color:#3b2a12}
.g6a-sh-pipe{margin-left:auto;font-size:28px;animation:g6awob 2s infinite}
.g6a-sh-clues{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;max-width:560px;margin:0 auto 6px}
.g6a-sh-c{position:relative;min-height:112px;border:1.5px solid var(--bd);border-radius:12px;background:var(--k);color:#fff;cursor:pointer;padding:6px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-width:0}
.g6a-sh-c .q{font-size:30px}.g6a-sh-c .e,.g6a-sh-c small{display:none}
.g6a-sh-c.on{background:#fffdf6;color:#222;animation:g6apop .4s}
.g6a-sh-c.on .q{display:none}.g6a-sh-c.on .e{display:block;font-size:30px}.g6a-sh-c.on small{display:block;font-size:13px;line-height:1.25;font-weight:700}
.g6a-sh-q{max-width:640px;margin:8px auto 2px;font-size:17px}
.g6a-sh-tl{display:flex;align-items:center;gap:8px;max-width:480px;margin:6px auto 10px}
.g6a-sh-tl .a,.g6a-sh-tl .b{text-align:center;background:var(--k);color:#fff;border-radius:10px;padding:6px 10px}
.g6a-sh-tl .b{background:#E3242B}
.g6a-sh-tl b{display:block;font-family:var(--fh)}.g6a-sh-tl small{font-size:11px}
.g6a-sh-tl .bar{flex:1;height:10px;background:#e3e8f0;border-radius:6px;overflow:hidden}
.g6a-sh-tl .bar i{display:block;height:100%;width:100%;background:repeating-linear-gradient(90deg,#FFD43B 0 10px,#f5b800 10px 20px);animation:g6agrow 1.4s ease}
@keyframes g6agrow{from{width:0}}
/* marathon */
.g6a-mr{max-width:360px;margin:0 auto 8px;background:#0B2A5B;border-radius:24px;padding:12px;color:#fff;border:3px solid #111;box-shadow:0 10px 24px rgba(0,0,0,.25)}
.g6a-mr.cramp{animation:shake .35s 2}
.g6a-mr-top{display:flex;justify-content:space-between;align-items:center;font-size:13px}
.g6a-mr-top b{font-family:var(--fh);font-size:17px;color:#FFD43B}
.g6a-mr-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:8px 0;text-align:center}
.g6a-mr-stats div{background:#12366f;border-radius:10px;padding:4px}
.g6a-mr-stats b{display:block;font-family:var(--fh);font-size:20px}.g6a-mr-stats small{font-size:11px;opacity:.8}
.g6a-mr-map{width:100%;height:auto;background:#0e3166;border-radius:12px}
.g6a-mr-map .pr{transition:stroke-dasharray .8s ease}
.g6a-mr-map .rn{transition:x .8s ease,y .8s ease}
.g6a-mr-q{max-width:640px;margin:0 auto}
.g6a-mr-cp{text-align:center;font-weight:800;color:#E3242B}
.g6a-mr-s{text-align:center;font-family:var(--fh);font-size:19px;color:var(--k);margin:6px 0;line-height:1.4}
.g6a-mr-fin{text-align:center;background:#FFF6D6;border:2px solid #FFD43B;border-radius:16px;padding:12px}
.g6a-mr-fin span{font-size:56px;display:block;animation:g6apop 1s 2}.g6a-mr-fin b{display:block;font-family:var(--fh);color:var(--k)}
/* taboo */
.g6a-tb-card{max-width:300px;margin:0 auto 8px;background:linear-gradient(#7c3aed,#5b21b6);border-radius:18px;padding:10px;color:#fff;box-shadow:0 8px 18px rgba(91,33,182,.35);text-align:center}
.g6a-tb-w{background:#fff;color:#5b21b6;border-radius:12px;padding:6px}
.g6a-tb-w span{font-size:34px;display:block}.g6a-tb-w b{font-family:var(--fh);font-size:24px;letter-spacing:2px}
.g6a-tb-card ul{list-style:none;margin:8px 0 6px;padding:0}
.g6a-tb-card li{font-weight:700;font-size:16px;text-decoration:line-through;text-decoration-color:#FFD43B;text-decoration-thickness:3px;opacity:.9}
.g6a-tb-card li::before{content:'🚫 '}
.g6a-tb-time{height:8px;background:rgba(255,255,255,.25);border-radius:6px;overflow:hidden}
.g6a-tb-time i{display:block;height:100%;width:100%;background:#FFD43B;transition:width .2s linear}
.g6a-tb-card.buzz{animation:shake .35s 2;background:linear-gradient(#E3242B,#9b1c22)}
.g6a-tb-card.ok{background:linear-gradient(#2E9E5B,#0B7A3B)}
.g6a-tb-def{max-width:600px;margin:0 auto 6px;text-align:center;font-family:var(--fh);font-size:19px;color:var(--k);line-height:1.4}
.g6a-tb-def .g3-rep{display:block;margin:6px auto 0}
.g6a-tb-pr{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;max-width:560px;margin:0 auto}
.g6a-tb-pr .opt{padding:12px 2px;font-size:16px}
@media (max-width:480px){.g6a-tb-pr{grid-template-columns:repeat(3,minmax(0,1fr))}}
.g6a-tb-e{display:block;font-size:30px}
/* fusion */
.g6a-fu{position:relative;display:flex;align-items:center;justify-content:space-between;gap:6px;max-width:600px;margin:0 auto 8px;min-height:130px}
.g6a-fu-at{width:42%;aspect-ratio:1;max-width:150px;border-radius:50%;display:flex;align-items:center;justify-content:center;text-align:center;padding:12px;font-weight:700;font-size:13.5px;line-height:1.25;color:#fff;transition:transform .7s ease;overflow-wrap:anywhere}
.g6a-fu-at.a{background:radial-gradient(circle at 30% 30%,#4f8cff,#0B2A5B);box-shadow:0 0 0 6px rgba(29,95,209,.2),0 0 0 12px rgba(29,95,209,.1)}
.g6a-fu-at.b{background:radial-gradient(circle at 30% 30%,#ff6b70,#9b1c22);box-shadow:0 0 0 6px rgba(227,36,43,.2),0 0 0 12px rgba(227,36,43,.1)}
.g6a-fu-core{font-size:30px;animation:g6aspin 4s linear infinite}
.g6a-fu.go .g6a-fu-at.a{transform:translateX(24%) scale(.9)}
.g6a-fu.go .g6a-fu-at.b{transform:translateX(-24%) scale(.9)}
.g6a-fu.go .g6a-fu-core{animation:g6aspin .3s linear infinite,g6aburst .7s 1}
.g6a-fu.ok .g6a-fu-core{animation:g6apop .5s 2;font-size:40px}
.g6a-fu.boom .g6a-fu-core{animation:shake .35s 2;font-size:40px}
.g6a-fu-cut{max-width:600px;margin:6px auto 12px;text-align:center;font-family:var(--fh);font-size:20px;color:var(--k);line-height:1.5}
.g6a-fu-cut .w{display:inline-block;background:#FFD43B;border-radius:8px;padding:0 8px;transition:all .6s}
.g6a-fu-cut .w.gone{transform:translateY(24px) rotate(20deg);opacity:.2;text-decoration:line-through}
.g6a-fu-cut .w.lock{background:#E7F8EE;outline:3px solid #2E9E5B}
.g6a-fu-cb{display:grid;grid-template-columns:1fr 1fr;gap:12px;max-width:420px;margin:0 auto}
.g6a-ng-pct{display:block;font-family:var(--fh);font-size:22px;color:var(--k);line-height:1}
/* END g6a */
/* examen final del curso */
.cx-list{display:grid;gap:8px;margin:12px auto;max-width:420px;text-align:left}
.cx-row{display:flex;align-items:center;gap:10px;border:2px solid #dde3ee;border-radius:12px;padding:10px 12px;font-weight:700}
.cx-row span{flex:1}.cx-row small{color:#4a5568}.cx-row.ok{border-color:#2E9E5B;background:#effcf3}
.pt-course{display:flex;align-items:center;gap:14px;margin-top:14px;text-decoration:none;color:inherit;border:2px solid #FFC21A;background:linear-gradient(135deg,#fff8e1,#fff)}
.pt-course h3{margin:2px 0}.pt-course p{margin:2px 0}
.pt-course-ic{font-size:44px;flex:none}
.pt-course-go{margin-left:auto;font-size:26px;flex:none}
.pt-course:not(.open):not(.done){filter:grayscale(.6);opacity:.85}
.pt-course.done{border-color:#2E9E5B}
.pt-cert.gold{border-color:#FFC21A;background:#fff8e1}
.pt-routebar .st.fin b{background:#FFC21A;border-color:#0B2A5B}
.pt-routebar .st.fin.locked b{opacity:.5}
@media (max-width:560px){.pt-routebar{padding:12px 8px}.pt-routebar .st b{width:36px;height:36px;font-size:15px}.pt-routebar .ln{margin:0 3px 20px}}

/* BEGIN clubs */
.cl-root{--cl-y:#FFC21A;--cl-r:#E3242B;--cl-k:#0B2A5B;--cl-sky:#EAF2FD;max-width:980px;margin:0 auto;color:var(--cl-k);font-family:var(--fb);overflow-wrap:anywhere}
.cl-root *{min-width:0}
.cl-root h1,.cl-root h2,.cl-root h3,.cl-root h4{font-family:var(--fh);font-weight:800;margin:0}
.cl-back{margin:0 0 14px}
.cl-dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--cl-r);box-shadow:0 0 0 0 rgba(227,36,43,.6);animation:clPulse 1.4s infinite;flex:none}
@keyframes clPulse{0%{box-shadow:0 0 0 0 rgba(227,36,43,.6)}70%{box-shadow:0 0 0 9px rgba(227,36,43,0)}100%{box-shadow:0 0 0 0 rgba(227,36,43,0)}}
.cl-onair{display:inline-flex;align-items:center;gap:7px;background:#fff;color:var(--cl-r);border:2px solid var(--cl-k);border-radius:999px;padding:4px 12px;font:800 12px/1 var(--fh);letter-spacing:2px}
.cl-onair.lock{color:var(--cl-k);background:var(--cl-y)}
.cl-hero{position:relative;overflow:hidden;background:var(--cl-k);color:#fff;border:2px solid var(--cl-k);border-radius:20px;box-shadow:3px 3px 0 var(--cl-r);padding:22px 20px;margin-bottom:22px;
  background-image:radial-gradient(circle at 12% -10%,rgba(255,194,26,.45),transparent 42%),radial-gradient(circle at 92% 0%,rgba(227,36,43,.55),transparent 45%)}
.cl-hero h1{font-size:clamp(26px,6vw,40px);margin:12px 0 6px;color:#fff}
.cl-hero p{margin:0;font-size:16px;line-height:1.5;color:#E6EEFB}
.cl-hero p b{color:#fff}
.cl-band{display:inline-block;background:var(--cl-y);color:var(--cl-k);font:800 13px/1 var(--fh);padding:4px 9px;border-radius:7px;letter-spacing:.5px}
.cl-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:20px}
.cl-card,.cl-poster{background:#fff;border:2px solid var(--cl-k);border-radius:20px;box-shadow:3px 3px 0 var(--cl-k);padding:18px;display:flex;flex-direction:column;gap:12px;position:relative;overflow:hidden}
.cl-card::before,.cl-poster::before{content:"";position:absolute;inset:0 0 auto 0;height:8px;background:repeating-linear-gradient(90deg,var(--cl-r) 0 18px,#fff 18px 26px,var(--cl-k) 26px 44px,#fff 44px 52px)}
.cl-card-top,.cl-poster-top{display:flex;gap:12px;align-items:center;margin-top:6px}
.cl-ic{font-size:30px;width:54px;height:54px;flex:none;display:grid;place-items:center;border:2px solid var(--cl-k);border-radius:16px;background:var(--cl-y);box-shadow:2px 2px 0 var(--cl-k)}
.cl-c-fon .cl-ic{background:#FFD6D8}
.cl-cname{font:800 19px/1.15 var(--fh)}
.cl-brand{font-size:13px;font-weight:700;color:var(--cl-r);letter-spacing:.3px}
.cl-what{margin:0;font-size:15px;line-height:1.45;color:var(--mut,#4A5B78)}
.cl-when{font-size:15px;line-height:1.5}
.cl-when span{color:var(--mut,#4A5B78);font-size:13px}
.cl-when.inv{color:#E6EEFB}.cl-when.inv b{color:#fff}
.cl-count{display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:var(--cl-sky);border:2px dashed var(--cl-k);border-radius:12px;padding:9px 12px;font-size:14px;font-weight:600}
.cl-count:empty{display:none}
.cl-count.live{background:var(--cl-r);color:#fff;border-style:solid;font-family:var(--fh);font-weight:800;letter-spacing:.5px}
.cl-count.live .cl-dot{background:#fff}
.cl-tease{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:3px;background:var(--cl-k);color:#fff;border-radius:14px;padding:12px 14px;border:2px solid var(--cl-k);transition:transform .1s}
.cl-tease:hover{transform:translate(-1px,-1px)}
.cl-tease:focus-visible{outline:3px solid var(--cl-y);outline-offset:2px}
.cl-tease-l{font:800 11px/1.2 var(--fh);letter-spacing:1.5px;color:var(--cl-y)}
.cl-tease-t{font:800 18px/1.2 var(--fh)}
.cl-tease-s{font-size:13px;color:#C9D7EE}
.cl-acts{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.cl-acts .btn{flex:1 1 150px}
.cl-nolink{flex:1 1 100%;font-size:14px;font-weight:600;background:#FFF6DB;border:2px dashed #C89400;border-radius:12px;padding:9px 12px;color:#6B4E00}
.cl-stage .cl-nolink{background:rgba(255,255,255,.12);border-color:var(--cl-y);color:#fff}
.cl-enter{background:var(--cl-r)!important;color:#fff!important;text-decoration:none}
.cl-mini{font-size:13px;color:var(--mut,#4A5B78);border-top:2px dotted #C9D7EE;padding-top:10px}
.cl-soon{background:#F3F6FB;border:2px dashed #9FB3D1;border-radius:14px;padding:12px;font-weight:600;font-size:14px}
.cl-soon.big{font-size:18px;padding:30px;text-align:center}
.cl-how{background:#fff;border:2px solid var(--cl-k);border-radius:18px;box-shadow:3px 3px 0 var(--cl-k);padding:18px;margin-top:24px}
.cl-how h3{font-size:20px;margin-bottom:8px}
.cl-how ol{margin:0;padding-left:20px;display:grid;gap:6px;line-height:1.5}
.cl-how p{margin:0 0 10px;line-height:1.5}
.cl-legend{display:flex;flex-wrap:wrap;gap:8px}
/* escenario del club */
.cl-stage{border:2px solid var(--cl-k);border-radius:20px;box-shadow:3px 3px 0 var(--cl-r);overflow:hidden;margin-bottom:16px;color:#fff;
  background:var(--cl-k);background-image:radial-gradient(ellipse at 20% -20%,rgba(255,194,26,.55),transparent 45%),radial-gradient(ellipse at 80% -20%,rgba(255,255,255,.25),transparent 40%),linear-gradient(180deg,transparent 70%,rgba(227,36,43,.35))}
.cl-stage.cl-c-fon{background-image:radial-gradient(ellipse at 15% -20%,rgba(227,36,43,.6),transparent 45%),radial-gradient(ellipse at 85% -20%,rgba(255,194,26,.35),transparent 40%)}
.cl-stage-in{padding:20px;display:flex;flex-direction:column;gap:10px;align-items:flex-start}
.cl-stage h1{font-size:clamp(24px,5.6vw,38px);line-height:1.1;color:#fff}
.cl-tag{margin:0;color:#E6EEFB;font-size:15px;line-height:1.45}
.cl-season{font:700 13px/1.3 var(--fh);background:rgba(255,255,255,.14);border:2px solid rgba(255,255,255,.35);border-radius:10px;padding:5px 10px}
.cl-stage .cl-count{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.5);color:#fff}
.cl-stage .cl-count.live{background:var(--cl-r)}
.cl-stage .btn{align-self:stretch;max-width:340px}
.cl-before{background:var(--cl-y);color:var(--cl-k);border-radius:12px;padding:9px 12px;font-weight:700;font-size:14px}
.cl-tabs{position:sticky;top:0;z-index:20;display:grid;grid-template-columns:repeat(4,1fr);gap:6px;background:#EEF4FC;padding:8px 0;margin-bottom:12px}
.cl-tab{border:2px solid var(--cl-k);background:#fff;color:var(--cl-k);border-radius:12px;padding:9px 4px;font:700 13px/1.15 var(--fh);box-shadow:2px 2px 0 var(--cl-k)}
.cl-tab.on{background:var(--cl-k);color:#fff;box-shadow:2px 2px 0 var(--cl-r)}
.cl-review{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;background:#FFF6DB;border:2px solid var(--cl-k);border-radius:14px;padding:10px 12px;margin-bottom:14px;font-weight:600;font-size:14px}
.cl-ep{background:#fff;border:2px solid var(--cl-k);border-radius:20px;box-shadow:3px 3px 0 var(--cl-k);padding:18px;display:grid;gap:14px}
.cl-ep-k{font:700 13px/1.4 var(--fh);color:var(--mut,#4A5B78);display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.cl-now{display:inline-block;background:var(--cl-r);color:#fff;font:800 11px/1 var(--fh);letter-spacing:1.5px;padding:5px 8px;border-radius:6px;white-space:nowrap}
.cl-ep-h{display:flex;gap:14px;align-items:center}
.cl-ep-emo{font-size:40px;width:68px;height:68px;flex:none;display:grid;place-items:center;background:var(--cl-y);border:2px solid var(--cl-k);border-radius:18px;box-shadow:3px 3px 0 var(--cl-k);transform:rotate(-4deg)}
.cl-ep-h h2{font-size:clamp(22px,5vw,30px);line-height:1.12}
.cl-es{color:var(--mut,#4A5B78);font-size:14px;margin-top:2px}
.cl-lbl{font:800 11px/1 var(--fh);letter-spacing:2px;text-transform:uppercase;margin-bottom:6px}
.cl-mission{background:var(--cl-y);border:2px solid var(--cl-k);border-radius:14px;padding:12px 14px;display:flex;flex-direction:column;gap:4px}
.cl-mission b{font:800 17px/1.3 var(--fh)}
.cl-mission span{font-size:14px}
.cl-goal{background:var(--cl-sky);border:2px solid var(--cl-k);border-radius:14px;padding:12px 14px;display:flex;flex-direction:column;gap:3px;font-size:15px}
.cl-goal i{font-size:13px;color:var(--mut,#4A5B78)}
.cl-sec{margin-top:22px}
.cl-sec-h{display:flex;flex-wrap:wrap;gap:8px;justify-content:space-between;align-items:center}
.cl-sec-h h3{font-size:21px}
.cl-help{margin:6px 0 12px;font-size:14px;line-height:1.45}
.cl-run{list-style:none;margin:0;padding:0;display:grid;gap:14px;counter-reset:st}
.cl-blk{position:relative;background:#fff;border:2px solid var(--cl-k);border-radius:16px;box-shadow:3px 3px 0 var(--cl-k);padding:14px 14px 14px 52px;counter-increment:st}
.cl-blk::before{content:counter(st);position:absolute;left:10px;top:12px;width:30px;height:30px;border-radius:50%;background:var(--cl-k);color:#fff;font:800 15px/30px var(--fh);text-align:center}
.cl-blk-h{display:flex;flex-wrap:wrap;gap:6px;justify-content:space-between;align-items:center;margin-bottom:6px}
.cl-kind{display:inline-flex;align-items:center;gap:5px;font:800 12px/1 var(--fh);letter-spacing:.5px;padding:5px 9px;border-radius:999px;border:2px solid var(--cl-k);background:var(--cl-sky);white-space:nowrap}
.cl-kd-hotseat .cl-kind{background:#FFD6D8}.cl-kd-roleplay .cl-kind{background:#E4ECFF}.cl-kd-icebreaker .cl-kind,.cl-kd-gamechat .cl-kind{background:#FFF0C2}
.cl-kd-debate .cl-kind{background:#E7F7EC}.cl-kd-storydice .cl-kind{background:#F1E8FF}.cl-kd-reflect .cl-kind{background:var(--cl-k);color:#fff}
.cl-min{font:700 12px/1 var(--fh);color:var(--mut,#4A5B78)}
.cl-blk h4{font-size:17px;line-height:1.25}
.cl-ins{margin:8px 0 10px;font-size:14px;line-height:1.5}
.cl-items{display:grid;gap:8px}
.cl-ph{display:flex;flex-wrap:wrap;gap:8px 10px;align-items:center;background:#F7FAFF;border:2px solid #C9D7EE;border-radius:12px;padding:8px 10px;transition:background .2s,border-color .2s}
.cl-ph.hl{background:#FFF6DB;border-color:var(--cl-y)}
.cl-ph-t{flex:1 1 180px;display:flex;flex-direction:column;gap:2px}
.cl-ph-t b{font-weight:700;font-size:15px;line-height:1.35}
.cl-ph-t span{font-size:13px;color:var(--mut,#4A5B78)}
.cl-ph-b{display:flex;gap:8px;align-items:center;flex:none}
.cl-ph.big{background:#fff;border:2px solid var(--cl-k);box-shadow:2px 2px 0 var(--cl-k);padding:12px}
.cl-ph.big .cl-ph-t b{font-family:var(--fh);font-size:17px}
.cl-play{width:42px;height:42px;flex:none;border-radius:50%;border:2px solid var(--cl-k);background:var(--cl-y);color:var(--cl-k);font-size:15px;font-weight:800;display:grid;place-items:center;box-shadow:2px 2px 0 var(--cl-k);padding:0}
.cl-play.playing{background:var(--cl-r);color:#fff}
.cl-play:active{transform:translate(2px,2px);box-shadow:none}
.cl-rec.rec{background:var(--cl-r)!important;color:#fff!important}
.cl-rec.rec .cl-dot{background:#fff}
.cl-fbbox{flex:1 1 100%}
.cl-fbbox:empty{display:none}
.cl-fb{border:2px solid var(--cl-k);border-radius:12px;padding:10px 12px;background:var(--cl-sky);font-size:14px;line-height:1.45;display:grid;gap:6px}
.cl-fb.ok{background:#DCFCE7;border-color:#16A34A}.cl-fb.mid{background:#FFF6DB;border-color:#C89400}.cl-fb.bad{background:#FEE2E2;border-color:#DC2626}
.cl-heard{font-size:13px;color:var(--mut,#4A5B78)}
.cl-marked .hit{color:#15803D;font-weight:700}.cl-marked .miss{color:#DC2626;font-weight:700;text-decoration:underline wavy}
.cl-bar{height:8px;border-radius:9px;background:#fff;border:2px solid var(--cl-k);overflow:hidden}
.cl-bar i{display:block;height:100%;width:0;background:var(--cl-r);animation:clBar linear forwards}
@keyframes clBar{to{width:100%}}
.cl-kitcta{all:unset;box-sizing:border-box;cursor:pointer;width:100%;margin-top:22px;display:flex;gap:12px;align-items:center;background:var(--cl-k);color:#fff;border:2px solid var(--cl-k);border-radius:16px;box-shadow:3px 3px 0 var(--cl-r);padding:14px 16px;font-size:14px;line-height:1.4}
.cl-kitcta>span{font-size:28px;flex:none}
.cl-kitcta div{flex:1}.cl-kitcta b{font-family:var(--fh);font-size:16px}
.cl-kitcta:focus-visible{outline:3px solid var(--cl-y);outline-offset:3px}
.cl-chal{margin-top:22px;background:#fff;border:2px solid var(--cl-k);border-radius:16px;padding:14px 16px;display:flex;flex-direction:column;gap:4px;box-shadow:3px 3px 0 var(--cl-y);
  background-image:linear-gradient(135deg,#FFF6DB 0,#fff 60%)}
.cl-chal b{font:800 16px/1.35 var(--fh)}.cl-chal span{font-size:14px}
.cl-stampbox{margin-top:22px;display:grid;gap:8px}
.cl-stampbox .btn{white-space:normal}
.cl-sub{font-size:13px;color:var(--mut,#4A5B78);line-height:1.4;text-align:center}
.cl-sub.inv{color:#E6EEFB}
.cl-stampok{margin-top:22px;display:flex;gap:14px;align-items:center;background:#DCFCE7;border:2px solid #16A34A;border-radius:16px;padding:14px;font-size:15px}
.cl-stampok.pop .cl-stamp{animation:clStamp .5s cubic-bezier(.3,1.6,.5,1)}
@keyframes clStamp{0%{transform:scale(2.2) rotate(-25deg);opacity:0}100%{transform:scale(1) rotate(-12deg);opacity:1}}
.cl-kitbar{margin-bottom:12px}
.cl-kit{display:grid;gap:12px}
/* mapa de temporada */
.cl-unit{background:#fff;border:2px solid var(--cl-k);border-radius:18px;box-shadow:3px 3px 0 var(--cl-k);padding:14px;margin-bottom:16px}
.cl-unit-h{display:flex;gap:10px;align-items:center;margin-bottom:10px}
.cl-unit-h>span{font-size:26px;flex:none}
.cl-unit-h b{font-family:var(--fh);font-size:16px;display:block}.cl-unit-h small{color:var(--mut,#4A5B78)}
.cl-eps{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,190px),1fr));gap:10px}
.cl-epx{position:relative;text-align:left;border:2px solid var(--cl-k);border-radius:14px;background:#fff;padding:10px 10px 10px 12px;display:grid;grid-template-columns:auto 1fr;gap:2px 8px;align-items:center;color:var(--cl-k);font-family:var(--fb);box-shadow:2px 2px 0 var(--cl-k)}
.cl-epx-n{position:absolute;top:6px;right:8px;font:800 11px/1 var(--fh);color:var(--mut,#4A5B78)}
.cl-epx-e{grid-row:span 2;font-size:24px}
.cl-epx-t{font:700 14px/1.2 var(--fh);padding-right:16px}
.cl-epx-s{font-size:12px;color:var(--mut,#4A5B78)}
.cl-epx.now{background:var(--cl-y);box-shadow:2px 2px 0 var(--cl-r)}
.cl-epx.now .cl-epx-s{color:var(--cl-r);font-weight:800}
.cl-epx.past.stamped{background:#DCFCE7}
.cl-epx.lock{background:#F3F6FB;border-style:dashed;box-shadow:none;color:#7B8BA6}
.cl-epx.lock .cl-epx-t{filter:blur(.6px);opacity:.75}
/* pasaporte */
.cl-pass{display:grid;gap:16px}
.cl-pass-cover{background:var(--cl-k);color:#fff;border:2px solid var(--cl-k);border-radius:20px;box-shadow:3px 3px 0 var(--cl-r);padding:18px;display:grid;gap:6px;text-align:center;
  background-image:radial-gradient(circle at 50% -30%,rgba(255,194,26,.5),transparent 55%)}
.cl-pass-k{font:800 11px/1.3 var(--fh);letter-spacing:2.5px;color:var(--cl-y)}
.cl-pass-name{font:800 24px/1.15 var(--fh)}
.cl-pass-lv{font:700 15px/1 var(--fh)}
.cl-pass-n{font-size:15px}.cl-pass-n b{font:800 30px/1 var(--fh);color:var(--cl-y)}
.cl-meter{height:12px;border-radius:9px;background:rgba(255,255,255,.2);border:2px solid #fff;overflow:hidden;width:100%;max-width:320px;margin:0 auto}
.cl-meter i{display:block;height:100%;background:var(--cl-y)}
.cl-stamps{display:grid;grid-template-columns:repeat(auto-fill,minmax(88px,1fr));gap:10px;background:#FFFBEF;border:2px solid var(--cl-k);border-radius:18px;padding:14px;
  background-image:repeating-linear-gradient(0deg,transparent 0 27px,rgba(11,42,91,.06) 27px 28px)}
.cl-slot{display:flex;flex-direction:column;align-items:center;gap:5px;text-align:center}
.cl-slot small{font-size:11px;line-height:1.2;color:var(--mut,#4A5B78);max-width:100%}
.cl-stamp{width:62px;height:62px;border-radius:50%;border:3px dashed #9FB3D1;display:grid;place-items:center;font:800 18px/1 var(--fh);color:#9FB3D1;background:#fff}
.cl-stamp.on{border:3px double var(--cl-r);color:var(--cl-r);font-size:28px;transform:rotate(-12deg);background:rgba(227,36,43,.06);box-shadow:inset 0 0 0 3px rgba(227,36,43,.25)}
.cl-stamp.sm{width:54px;height:54px;flex:none}
.cl-slot.cur .cl-stamp:not(.on){border-color:var(--cl-r);color:var(--cl-r)}
/* vitrina */
.cl-hero.lock{box-shadow:3px 3px 0 var(--cl-y)}
.cl-peek{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.cl-peek li{background:#F7FAFF;border:2px solid #C9D7EE;border-radius:10px;padding:7px 10px;font-weight:600;font-size:14px}
.cl-peek li.blur{filter:blur(3px);user-select:none}
.cl-peek .cl-peek-more{background:var(--cl-k);color:#fff;border-color:var(--cl-k);text-align:center}
.cl-plan{margin-top:24px;background:#fff;border:2px solid var(--cl-k);border-radius:20px;box-shadow:3px 3px 0 var(--cl-r);padding:20px;display:grid;gap:12px}
.cl-plan h3{font-size:21px}
.cl-plan ul{list-style:none;margin:0;padding:0;display:grid;gap:6px;font-size:15px}
.cl-wa{background:#25D366!important;color:#fff!important;text-decoration:none}
/* guía del profe */
.cl-gunit{margin-top:22px}
.cl-gunit-h{font-size:19px;margin-bottom:10px}.cl-gunit-h small{font:600 13px var(--fb);color:var(--mut,#4A5B78)}
.cl-gs{background:#fff;border:2px solid var(--cl-k);border-radius:16px;box-shadow:3px 3px 0 var(--cl-k);margin-bottom:12px;overflow:hidden}
.cl-gs.now{box-shadow:3px 3px 0 var(--cl-r);border-color:var(--cl-r)}
.cl-gs summary{list-style:none;cursor:pointer;display:flex;gap:10px;align-items:center;padding:12px 14px}
.cl-gs summary::-webkit-details-marker{display:none}
.cl-gs summary::after{content:"▾";margin-left:auto;font-size:18px;transition:transform .2s;flex:none}
.cl-gs[open] summary::after{transform:rotate(180deg)}
.cl-gs[open] summary{border-bottom:3px solid var(--cl-k);background:var(--cl-sky)}
.cl-gs-n{width:34px;height:34px;flex:none;border-radius:10px;background:var(--cl-k);color:#fff;font:800 15px/34px var(--fh);text-align:center}
.cl-gs-t{display:flex;flex-direction:column;gap:2px;flex:1}
.cl-gs-t b{font-family:var(--fh);font-size:16px;line-height:1.2}.cl-gs-t small{color:var(--mut,#4A5B78);font-size:13px}
.cl-gs-b{padding:14px;display:grid;gap:12px}
.cl-gh{font-size:16px;margin-top:6px}
.cl-steps{margin:0;padding-left:22px;display:grid;gap:8px;font-size:14px;line-height:1.5}
.cl-guide .cl-chal{margin-top:0}
.cl-guide .cl-stage .row{gap:8px}
/* aviso */
.cl-toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,140%);max-width:min(92vw,420px);background:var(--k,#0B2A5B);color:#fff;border:2px solid #fff;border-radius:14px;padding:12px 16px;font-weight:700;font-size:15px;z-index:9999;box-shadow:0 6px 16px rgba(227,36,43,.25);transition:transform .25s;text-align:center}
.cl-toast.on{transform:translate(-50%,0)}
@media (max-width:560px){
  .cl-hero,.cl-stage-in{padding:18px 16px}
  .cl-card,.cl-poster,.cl-ep{padding:15px}
  .cl-blk{padding:12px 12px 12px 46px}.cl-blk::before{left:8px;width:28px;height:28px;line-height:28px}
  .cl-tab{font-size:12px;padding:8px 2px}
  .cl-ep-emo{width:58px;height:58px;font-size:32px}
  .cl-stamps{grid-template-columns:repeat(auto-fill,minmax(74px,1fr));padding:10px}
  .cl-stamp{width:54px;height:54px}
}
@media print{
  .cl-guide .btn,.cl-guide .cl-play{display:none!important}
  .cl-gs{break-inside:avoid-page;box-shadow:none}
  .cl-stage,.cl-hero{box-shadow:none}
}
/* END clubs */

/* BEGIN in */
.in-page [hidden]{display:none!important}
.in-wrap{max-width:1080px}
.in-page a.btn{text-decoration:none}
.in-hero{display:grid;grid-template-columns:1.5fr 1fr;gap:18px;align-items:center;background:#fff;border:1.5px solid var(--bd);border-radius:var(--r);box-shadow:var(--sh2);padding:24px 26px;position:relative;overflow:hidden}
.in-hero::after{content:"";position:absolute;right:-60px;top:-60px;width:220px;height:220px;border-radius:50%;background:var(--y3);z-index:0}
.in-hero>*{position:relative;z-index:1}
.in-hero h1{font-size:clamp(27px,4.4vw,44px);font-weight:800;margin:12px 0 10px}
.in-hl{background:var(--y);color:#fff;padding:0 8px;border-radius:8px;box-decoration-break:clone;-webkit-box-decoration-break:clone}
.in-hero p{font-size:17px;line-height:1.5;margin:0 0 12px}
.in-hero-pts{list-style:none;padding:0;margin:0;display:flex;flex-wrap:wrap;gap:8px}
.in-hero-pts li{border:1.5px solid var(--bd);border-radius:999px;padding:5px 12px;font-weight:700;font-size:14px;background:var(--paper)}
.in-hero-img{width:auto;max-width:100%;height:auto;max-height:380px;justify-self:center;object-fit:contain}
.in-card>.in-f{margin-top:20px}
.in-step{display:flex;align-items:center;gap:10px;font-size:24px;margin:30px 0 14px}
.in-step span{display:inline-grid;place-items:center;width:38px;height:38px;border-radius:50%;background:var(--y);color:#fff;border:1.5px solid var(--bd);font-size:18px;flex:none}
.in-plans{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;align-items:stretch}
@media (max-width:1100px) and (min-width:861px){.in-plans{grid-template-columns:repeat(2,minmax(0,1fr))}}
.in-plan{position:relative;display:flex;flex-direction:column;gap:6px;text-align:left;background:#fff;border:1.5px solid var(--bd);border-radius:var(--r);box-shadow:var(--sh);padding:22px 18px 16px;color:var(--k);font-family:var(--fb);font-size:15px;transition:transform .1s,box-shadow .1s;min-width:0}
.in-plan:hover{transform:translate(-2px,-2px);box-shadow:0 6px 18px rgba(11,42,91,.12)}
.in-plan:focus-visible{outline:4px solid var(--blue);outline-offset:3px}
.in-plan.best{border-color:var(--y);box-shadow:0 6px 16px rgba(227,36,43,.25)}
.in-plan.on{background:var(--y3);box-shadow:0 6px 18px rgba(11,42,91,.12);border-color:var(--k)}
.in-plan.best.on{box-shadow:0 6px 16px rgba(227,36,43,.25)}
.in-ribbon{position:absolute;top:-15px;left:50%;transform:translateX(-50%);background:var(--y);color:#fff;border:1.5px solid var(--bd);border-radius:999px;padding:4px 12px;font-family:var(--fh);font-weight:800;font-size:13px;white-space:nowrap}
.in-plan-ic{font-size:30px;line-height:1}
.in-plan-name{font-family:var(--fh);font-weight:800;font-size:21px}
.in-plan-price b{font-family:var(--fh);font-size:30px;font-weight:800}
.in-plan-price small{font-weight:700;color:var(--mut);margin-left:4px}
.in-plan-tag{align-self:flex-start;background:var(--k);color:#fff;font-weight:800;font-size:12px;letter-spacing:.5px;text-transform:uppercase;padding:3px 9px;border-radius:6px}
.in-plan ul{list-style:none;padding:0;margin:8px 0 4px;display:grid;gap:7px;flex:1}
.in-plan li{padding-left:24px;position:relative;line-height:1.35}
.in-plan li::before{content:"✓";position:absolute;left:0;top:0;width:18px;height:18px;border-radius:50%;background:var(--ok2);color:var(--ok);font-weight:800;font-size:12px;display:grid;place-items:center;border:1.5px solid var(--ok)}
.in-plan-note{font-size:13px;color:var(--mut);font-style:italic}
.in-plan-pick{margin-top:8px;text-align:center;border:1.5px solid var(--bd);border-radius:12px;padding:9px;font-family:var(--fh);font-weight:800;background:#fff}
.in-plan.on .in-plan-pick{background:var(--k);color:#fff}
.in-card{padding:22px}
.in-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 18px}
.in-f{display:flex;flex-direction:column;gap:5px;min-width:0}
.in-f label,.in-fs legend{font-weight:800;font-size:15px}
.in-form .inp{font-size:16px;font-family:var(--fb);font-weight:600;text-align:left;padding:12px 14px;min-height:50px;width:100%;max-width:100%}
.in-form textarea.inp{resize:vertical;min-height:90px}
.in-form select.inp{appearance:auto}
.in-form .inp.in-bad{border-color:var(--bad);background:var(--bad2)}
.in-form small{font-size:13px}
.in-err{color:var(--bad);font-weight:700;font-size:14px;margin:2px 0 0}
.in-fs{border:0;padding:0;margin:20px 0 0;min-width:0}
.in-fs legend{padding:0;margin-bottom:8px}
.in-chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:6px}
.in-chip{border:1.5px solid var(--bd);background:#fff;color:var(--k);border-radius:12px;padding:9px 14px;font-family:var(--fh);font-weight:700;font-size:15px;box-shadow:0 6px 18px rgba(11,42,91,.12);display:inline-flex;flex-direction:column;align-items:center;line-height:1.2}
.in-chip small{font-family:var(--fb);font-weight:600;font-size:12px;color:var(--mut)}
.in-chip.on{background:var(--k);color:#fff}
.in-chip.on small{color:#cfe0ff}
.in-chip:active{transform:translate(2px,2px);box-shadow:0 6px 18px rgba(11,42,91,.12)}
.in-cond{margin-top:6px;padding:4px 0 0}
#in-premium{background:var(--y3);border:2px dashed var(--k);border-radius:14px;padding:4px 16px 14px;margin-top:20px}
#in-pay{margin-top:20px}
.in-tip{font-size:14px;margin:12px 0 0;font-weight:600}
.in-consent{display:flex;gap:12px;align-items:flex-start;margin-top:22px;font-size:14px;line-height:1.45;background:var(--paper);border:1.5px solid var(--bd);border-radius:12px;padding:12px 14px;cursor:pointer}
.in-consent input{width:22px;height:22px;flex:none;margin:1px 0 0;accent-color:var(--y)}
.in-summary{margin:18px 0 12px;font-weight:600;text-align:center}
.in-small{font-size:14px;margin:12px 0 0}
.in-small a{color:var(--blue);font-weight:700}
.in-modal{position:fixed;inset:0;z-index:9000;background:rgba(11,42,91,.6);display:grid;place-items:center;padding:16px}
.in-modal-card{max-width:440px;width:100%}
.in-modal-card h3{font-size:22px;margin:6px 0}
.in-modal-img{height:130px;width:auto}
.in-done{max-width:640px;margin:10px auto}
.in-done h1{font-size:clamp(26px,5vw,36px);margin:12px 0 8px}
.in-done p{font-size:17px;line-height:1.5}
.in-done-img{width:auto!important;max-width:100%;height:auto;max-height:230px}
.in-next{text-align:left;max-width:440px;margin:14px auto 20px;padding-left:22px;display:grid;gap:6px;font-size:16px}
.btn.in-wa{background:#16A34A;color:#fff}
.in-confetti{position:fixed;inset:0;width:100vw;height:calc(100vh / var(--z, 1));pointer-events:none;z-index:9999}
@media (max-width:860px){
  .in-plans{grid-template-columns:1fr;gap:22px}
  .in-hero{grid-template-columns:1fr;padding:20px 18px}
  .in-hero-img{max-height:210px;grid-row:1}
}
@media (max-width:560px){
  .in-grid{grid-template-columns:1fr}
  .in-card{padding:16px}
  .in-step{font-size:21px}
  .in-hero p{font-size:16px}
}
/* END in */

/* BEGIN tp */
.tp-wrap{max-width:1120px}
.tp-page a.btn{text-decoration:none}
.tp-login{max-width:480px;margin:20px auto}
.tp-login h1{font-size:30px;margin:10px 0 6px}
.tp-login-img{height:170px;width:auto}
.tp-lform{display:grid;gap:6px;text-align:left;margin-top:14px}
.tp-lform label{font-weight:800;font-size:15px;margin-top:6px}
.tp-lform .inp,.tp-inp{font-size:16px;font-family:var(--fb);font-weight:600;text-align:left;padding:11px 14px;min-height:48px;max-width:100%}
.tp-lform #tp-code{text-transform:uppercase}
.tp-lform .btn{margin-top:10px}
.tp-err{color:var(--bad);font-weight:700;margin:4px 0 0}
.tp-small{font-size:14px}
.tp-loading{text-align:center;padding:60px 0;font-weight:700;color:var(--mut)}
.tp-head{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:14px}
.tp-head-txt{flex:1;min-width:0}
.tp-head h1{font-size:clamp(24px,4vw,32px)}
.tp-head p{margin:4px 0 0}
.tp-chat{flex:none}
.tp-tabs{display:flex;gap:8px;margin-bottom:16px;overflow-x:auto;padding:2px 6px 8px 2px;scrollbar-width:thin}
.tp-tab{flex:none;border:1.5px solid var(--bd);background:#fff;color:var(--k);border-radius:12px;padding:10px 14px;font-family:var(--fh);font-weight:700;font-size:15px;box-shadow:0 6px 18px rgba(11,42,91,.12);white-space:nowrap}
.tp-tab.on{background:var(--k);color:#fff}
.tp-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}
.tp-stat{background:#fff;border:1.5px solid var(--bd);border-radius:16px;box-shadow:var(--sh);padding:14px;display:flex;flex-direction:column;gap:2px}
.tp-stat b{font-family:var(--fh);font-size:32px;line-height:1}
.tp-stat span{font-size:14px;font-weight:600;color:var(--mut)}
.tp-stat.red{background:var(--y);color:#fff}
.tp-stat.red span{color:#fff}
.tp-alert{background:var(--y3);border:1.5px solid var(--bd);border-radius:14px;padding:12px 14px;margin:0 0 16px;font-size:15px;line-height:1.45}
.tp-alert.warn{background:#FFF4D6}
.tp-alert .btn{margin-left:6px;margin-top:4px}
.tp-card{padding:18px;margin-bottom:16px;min-width:0}
.tp-card-h{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px}
.tp-card-h h2{font-size:21px}
.tp-list{list-style:none;padding:0;margin:0;display:grid;gap:10px}
.tp-cls{display:grid;grid-template-columns:170px minmax(0,1fr) auto;gap:12px;align-items:center;border:1.5px solid var(--bd);border-radius:14px;padding:12px;background:#fff}
.tp-cls.today{background:#FFF0F0;border-color:var(--y);border-width:3px}
.tp-cls.tomorrow{background:var(--y3)}
.tp-cls-when b{display:block;font-family:var(--fh);font-size:17px}
.tp-cls.today .tp-cls-when b{color:var(--y)}
.tp-cls-when span{font-size:14px;color:var(--mut);font-weight:600}
.tp-cls-what{display:flex;flex-wrap:wrap;gap:4px 6px;align-items:center;min-width:0}
.tp-cls-who{flex-basis:100%;font-weight:700;overflow-wrap:anywhere}
.tp-cls-what small{flex-basis:100%}
.tp-note{background:var(--paper);border-radius:8px;padding:4px 8px}
.tp-cls-act{display:flex;flex-direction:column;gap:6px;align-items:stretch}
.tp-badge{display:inline-block;font-size:12px;font-weight:800;letter-spacing:.4px;border:1.5px solid var(--bd);border-radius:6px;padding:1px 7px}
.tp-badge.vip{background:var(--y);color:#fff}
.tp-badge.grp{background:var(--k);color:#fff}
.tp-st{display:inline-block;font-size:12px;font-weight:800;border-radius:999px;padding:2px 9px;border:2px solid currentColor}
.tp-st.done,.tp-st.free{color:var(--ok);background:var(--ok2)}
.tp-st.noshow{color:var(--bad);background:var(--bad2)}
.tp-st.canc{color:#6B7280;background:#F3F4F6}
.tp-st.pend{color:#B45309;background:#FEF3C7}
.tp-st.sch{color:var(--blue);background:var(--y3)}
.tp-st.booked{color:#fff;background:var(--k);border-color:var(--k)}
.tp-empty{display:flex;align-items:center;gap:14px;padding:6px 0}
.tp-empty img{width:auto!important;height:110px;max-height:110px;flex:none}
.tp-empty p{margin:0}
.tp-cols{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:start}
.tp-l{display:block;font-weight:800;font-size:15px;margin:14px 0 6px}
.tp-hours{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.tp-hour{border:1.5px solid var(--bd);background:#fff;color:var(--k);border-radius:10px;padding:8px 2px;font-weight:700;font-size:14px;white-space:nowrap}
.tp-hour.on{background:var(--k);color:#fff;box-shadow:0 6px 16px rgba(227,36,43,.25)}
.tp-hour.past{opacity:.4}
.tp-other{display:flex;align-items:center;gap:8px;margin-top:10px;flex-wrap:wrap}
.tp-other label{font-weight:700;font-size:14px}
.tp-other .inp{width:auto;flex:1;min-width:120px}
.tp-seg{display:inline-flex;border:1.5px solid var(--bd);border-radius:12px;overflow:hidden;background:#fff;max-width:100%}
.tp-segb{border:0;border-right:1.5px solid var(--bd);background:#fff;color:var(--k);padding:9px 14px;font-family:var(--fh);font-weight:700;font-size:15px}
.tp-segb:last-child{border-right:0}
.tp-segb.on{background:var(--k);color:#fff}
.tp-subtabs{margin-bottom:14px}
.tp-rep{display:flex;align-items:center;gap:10px;margin-top:16px;font-weight:800;cursor:pointer}
.tp-rep input{width:22px;height:22px;accent-color:var(--y)}
.tp-weeks{display:flex;align-items:center;gap:8px;margin:8px 0 0 32px}
.tp-weeks .inp{width:auto}
.tp-preview{margin:16px 0 12px;background:var(--paper);border:2px dashed var(--k);border-radius:12px;padding:10px 12px;font-size:14px;line-height:1.45}
.tp-day h3{font-size:16px;margin:14px 0 6px;font-family:var(--fh)}
.tp-day:first-of-type h3{margin-top:0}
.tp-rel{background:var(--y);color:#fff;border-radius:6px;padding:1px 7px;font-size:13px}
.tp-day ul{list-style:none;padding:0;margin:0;display:grid;gap:6px}
.tp-slot{display:flex;align-items:center;gap:8px;flex-wrap:wrap;border:1.5px solid var(--bd);border-radius:12px;padding:8px 10px;background:#fff}
.tp-slot.booked{background:var(--y3)}
.tp-slot-t{font-weight:800;flex:1;min-width:150px}
.tp-slot-t small{display:block;font-weight:600;color:var(--mut);font-size:12px}
.tp-slot-who{flex-basis:100%;font-weight:700;font-size:14px}
.tp-del{border:1.5px solid var(--bd);background:#fff;border-radius:10px;width:40px;height:40px;font-size:17px;display:grid;place-items:center}
.tp-del:hover{background:var(--bad2)}
.tp-modal{position:fixed;inset:0;z-index:9000;background:rgba(11,42,91,.6);display:grid;place-items:center;padding:16px;overflow-y:auto}
.tp-modal-card{position:relative;max-width:480px;width:100%;max-height:calc(calc(100vh / var(--z, 1)) - 32px);overflow-y:auto}
.tp-modal-card h3{font-size:22px;margin:0 30px 6px 0}
.tp-x{position:absolute;top:10px;right:10px;border:1.5px solid var(--bd);background:#fff;border-radius:10px;width:36px;height:36px;font-weight:800}
.tp-att{display:grid;gap:6px}
.tp-attrow{display:flex;align-items:center;gap:10px;border:1.5px solid var(--bd);border-radius:12px;padding:9px 12px;cursor:pointer}
.tp-attrow input{width:22px;height:22px;accent-color:var(--ok);flex:none}
.tp-attrow span{font-weight:700;flex:1;min-width:0;overflow-wrap:anywhere}
.tp-attrow small{color:var(--mut)}
.tp-mbtns{justify-content:flex-end;margin-top:14px;flex-wrap:wrap-reverse}
.tp-mbtns .btn{flex:1 1 180px}
.tp-groups{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px}
.tp-group{padding:18px;min-width:0}
.tp-group-h{display:flex;align-items:center;gap:8px;justify-content:space-between}
.tp-group-h h2{font-size:20px}
.tp-group-when{font-weight:700;margin:8px 0}
.tp-studs{list-style:none;padding:0;margin:0 0 12px;display:grid;gap:6px}
.tp-studs li{display:flex;align-items:center;gap:10px}
.tp-studs small{display:block;color:var(--mut);font-size:12px}
.tp-av{width:34px;height:34px;border-radius:50%;background:var(--k);color:#fff;display:grid;place-items:center;font-weight:800;flex:none}
.tp-toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,160%);max-width:min(92vw,440px);background:var(--k);color:#fff;border:2px solid #fff;border-radius:14px;padding:12px 16px;font-weight:700;font-size:15px;z-index:9999;box-shadow:0 6px 16px rgba(227,36,43,.25);transition:transform .25s;text-align:center}
.tp-toast.on{transform:translate(-50%,0)}
.tp-toast.bad{background:var(--bad)}
@media (max-width:900px){
  .tp-cols{grid-template-columns:1fr}
  .tp-stats{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:640px){
  .tp-tabs{display:grid;grid-template-columns:1fr 1fr;overflow:visible;padding:0 4px 4px 0}
  .tp-tab{padding:10px 6px;font-size:14px;white-space:normal}
  .tp-cls{grid-template-columns:1fr;gap:8px}
  .tp-cls-act{flex-direction:row;flex-wrap:wrap}
  .tp-cls-act .btn{flex:1 1 auto}
  .tp-hours{grid-template-columns:repeat(3,minmax(0,1fr))}
  .tp-card{padding:14px}
  .tp-stat b{font-size:26px}
  .tp-chat{width:100%}
  .tp-groups{grid-template-columns:1fr}
  .tp-segb{padding:9px 10px;font-size:14px}
  .tp-empty{flex-direction:column;text-align:center}
}
/* END tp */
/* BEGIN rc */
.rc{max-width:900px}
.rc-steps{list-style:none;display:flex;gap:6px;margin:0 0 16px;padding:0;counter-reset:none}
.rc-steps li{flex:1;min-width:0;display:flex;align-items:center;gap:6px;background:#fff;border:1.5px solid var(--bd);border-radius:12px;padding:6px 8px;font-weight:700;font-size:13px;opacity:.6}
.rc-steps li b{flex:none;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:var(--y3);border:1.5px solid var(--bd);font-size:12px}
.rc-steps li span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.rc-steps li.on{opacity:1;background:var(--k);color:#fff}
.rc-steps li.on b{background:#E3242B;color:#fff;border-color:#fff}
.rc-steps li.ok{opacity:1}
.rc-steps li.ok b{background:var(--ok);color:#fff;border-color:var(--k)}
.rc-hero-top,.rc-res-top{display:flex;gap:16px;align-items:center}
.rc-mascot{width:120px;height:auto;flex:none}
.rc-h1{font-size:clamp(24px,5vw,34px);margin:10px 0 6px}
.rc-h2{font-size:clamp(22px,4.6vw,28px);margin:10px 0 6px;overflow-wrap:anywhere}
.rc-h3{font-size:18px;margin:18px 0 6px}
.rc-lead{font-size:17px;margin:0}
.rc-grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:16px 0 4px}
.rc-box{border:1.5px solid var(--bd);border-radius:14px;padding:12px;background:var(--y3);display:flex;flex-direction:column;gap:4px}
.rc-box span{width:30px;height:30px;border-radius:50%;background:#E3242B;color:#fff;font-family:var(--fh);font-weight:800;display:grid;place-items:center;border:1.5px solid var(--bd)}
.rc-box small{color:var(--mut)}
.rc-need{line-height:1.6;padding-left:4px;list-style:none;margin:0}.rc-need li{margin:6px 0}
.rc-cols{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}
.rc-f{margin-top:12px;min-width:0}
.rc-f label,.rc-lab{display:block;font-weight:800;margin:0 0 5px}
.rc-form .inp{text-align:left;font-size:17px;font-family:var(--fb);font-weight:600;padding:12px 14px}
.rc-form select.inp{appearance:auto;background:#fff}
.rc-form textarea.inp{resize:vertical;min-height:110px;line-height:1.45}
.rc-form .inp.rc-bad{border-color:var(--bad);background:var(--bad2)}
.rc-err{display:block;color:var(--bad);font-weight:700;font-size:14px;min-height:0;margin-top:4px}
.rc-err:empty{display:none}
.rc-chks{display:flex;flex-wrap:wrap;gap:8px}
.rc-chk{display:inline-flex!important;align-items:center;gap:8px;border:1.5px solid var(--bd);border-radius:12px;padding:9px 12px;background:#fff;cursor:pointer;font-weight:700!important;margin:0!important;user-select:none}
.rc-chk input{width:20px;height:20px;accent-color:#E3242B;margin:0}
.rc-chk:has(input:checked){background:var(--y3);box-shadow:0 6px 18px rgba(11,42,91,.12)}
.rc-file{display:flex!important;align-items:center;gap:12px;border:3px dashed var(--k);border-radius:14px;padding:14px;background:var(--paper);cursor:pointer;font-weight:600!important;margin:0!important;min-width:0}
.rc-file input{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}
.rc-file:focus-within{box-shadow:0 0 0 4px var(--y)}
.rc-file-ic{font-size:30px;flex:none}
.rc-file-t{min-width:0;overflow-wrap:anywhere}.rc-file-t em{color:var(--mut);font-style:normal;font-size:14px}
.rc-consent{display:flex;gap:10px;align-items:flex-start;margin-top:16px;font-size:14.5px;line-height:1.45;cursor:pointer;background:var(--y3);border:1.5px solid var(--bd);border-radius:12px;padding:10px 12px}
.rc-consent input{width:22px;height:22px;flex:none;accent-color:#E3242B;margin:1px 0 0}
.rc-sk{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:12px 0}
.rc-sk div{border:1.5px solid var(--bd);border-radius:12px;padding:8px 4px;background:var(--y3);font-weight:700;font-size:13.5px;text-align:center}
.rc-sk b{display:block;font-family:var(--fh);font-size:24px}
.rc-mic{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1.5px solid var(--bd);border-radius:14px;padding:12px;margin-top:12px;background:#fff;flex-wrap:wrap}
.rc-mic>div{min-width:0;flex:1 1 220px}
.rc-mic.ok{background:var(--ok2)}.rc-mic.bad{background:var(--bad2)}
.rc-top{display:flex;align-items:center;gap:8px;margin-bottom:10px}
.rc-who{font-weight:800;margin-left:auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
.rc-hd{display:flex;align-items:center;gap:8px;margin-bottom:12px}
.rc-desc{font-size:17px;max-width:620px;margin:8px auto}
.rc-item .opt.rc-sel{background:var(--y3)!important;border-color:#E3242B;box-shadow:0 6px 16px rgba(227,36,43,.25)}
.rc-item .opt.rc-sel .qs-l{background:#E3242B;color:#fff}
.rc-tf{margin:-6px 0 10px}
.rc-ans{max-width:420px;margin:0 auto}.rc-ans .inp{text-align:center;font-size:20px}
.rc-hint{font-size:14px;margin:8px 0 0}
.rc-left{text-align:left}.rc-ex{font-size:15px;font-style:italic}
.rc-ta{min-height:140px;font-size:17px!important;font-family:var(--fb)!important;font-weight:500!important;text-align:left!important}
.rc-wc{font-size:14px;margin:6px 0 0;text-align:right}
.rc-min{font-weight:700;font-size:14px;margin-top:6px}
.rc-saved{max-width:560px;margin-left:auto;margin-right:auto}
.rc-rev{max-height:calc(40vh / var(--z, 1))}
.rc-warn{background:var(--bad2);border:2px solid var(--bad);border-radius:12px;padding:10px;font-weight:700}
.rc-bar{height:18px;border:1.5px solid var(--bd);border-radius:99px;background:#fff;overflow:hidden;max-width:520px;margin:16px auto 8px}
.rc-bar i{display:block;height:100%;width:0;background:#E3242B;transition:width .3s}
.rc-ptxt{font-weight:800}
.rc-res-top{justify-content:center;text-align:left}
.rc-badge{display:inline-block;font-family:var(--fh);font-weight:800;font-size:clamp(20px,5vw,26px);border:1.5px solid var(--bd);border-radius:14px;padding:6px 14px;margin-top:4px;box-shadow:var(--sh)}
.rc-badge.ok{background:var(--ok2);color:#14532d}.rc-badge.no{background:#fff;color:#b91c1c}
.rc-msg{font-size:17px;max-width:620px;margin:14px auto;line-height:1.5}
.rc-bars .bar{height:14px;border:1.5px solid var(--bd);border-radius:99px;background:#fff;overflow:hidden}
.rc-bars .bar i{display:block;height:100%;background:#E3242B}
.rc-small{font-size:14px}
.rc-st{display:grid;gap:6px;text-align:left;font-size:14.5px;max-width:620px;margin:10px auto}
.rc-st div{border-radius:10px;padding:8px 12px;background:#f4f4f5;overflow-wrap:anywhere}.rc-st .ok{background:var(--ok2)}.rc-st .err{background:var(--bad2)}
.rc-btns{justify-content:center;margin-top:12px}
.rc-wa{background:#25D366!important;color:#fff!important;text-decoration:none}
.rc .rc-form .actionbar,.rc .rc-hero .actionbar{position:static}
@media (max-width:700px){
  .rc-steps li{flex:0 0 auto;padding:5px}
  .rc-steps li span{display:none}
  .rc-steps li.on{flex:1 1 auto}.rc-steps li.on span{display:inline}
  .rc-hero-top,.rc-res-top{flex-direction:column;text-align:center}
  .rc-mascot{width:96px}
  .rc-grid3,.rc-cols{grid-template-columns:1fr}
  .rc-sk{grid-template-columns:repeat(2,minmax(0,1fr))}
  .rc .actionbar .btn.lg{padding:14px 18px;font-size:17px}
  .rc .card{padding:16px}
}
/* END rc */
/* BEGIN plans */
.pl-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:12px}
.pl-grid.n1{max-width:420px}
.pl-card{position:relative;background:#fff;border:1.5px solid var(--bd);border-radius:18px;box-shadow:var(--sh);padding:18px 16px 16px;display:flex;flex-direction:column;gap:6px;min-width:0}
.pl-card.premium{background:linear-gradient(160deg,#fff 0%,#FFF1F1 100%);border-color:var(--y);box-shadow:0 6px 16px rgba(227,36,43,.25)}
.pl-card h3{font-size:21px}
.pl-rib{position:absolute;top:-13px;right:12px;background:var(--y);color:#fff;font:800 12px var(--fh);padding:4px 10px;border-radius:999px;border:1.5px solid var(--bd)}
.pl-price b{font:800 28px var(--fh)}.pl-price small{font-weight:700;color:var(--mut);margin-left:3px}
.pl-tag{margin:0;font-weight:700;color:var(--k2);font-size:14.5px}
.pl-card ul{margin:6px 0 10px;padding:0;list-style:none;display:grid;gap:5px;font-size:15px}
.pl-card li{padding-left:24px;position:relative}.pl-card li:before{content:'✔';position:absolute;left:2px;color:var(--ok);font-weight:900}
.pl-go{margin-top:auto;text-decoration:none}
.pl-on{margin-top:auto;text-align:center;font-weight:800;color:var(--ok)}
.pl-note{font-size:14px;color:var(--mut);margin:10px 2px 0}
.pl-mine{display:flex;gap:14px;align-items:center;margin-bottom:6px}
.pl-mine-ic{font-size:40px;width:64px;height:64px;flex:none;border-radius:16px;border:1.5px solid var(--bd);display:grid;place-items:center;background:var(--y3)}
.pl-mine.premium .pl-mine-ic{background:#FFE3E4}.pl-mine.exp{border-color:var(--bad)}.pl-mine.exp .pl-mine-ic{background:var(--bad2)}
.pl-mine h2{font-size:24px;margin:6px 0 2px}.pl-mine p{margin:0}
.pl-warn{color:var(--bad)}
.pt-hint{display:block;color:var(--mut);font-size:13.5px;margin:4px 2px 0}
.pt-ann{background:#FFF8D6;border:1.5px solid var(--bd);border-radius:14px;padding:12px 14px;margin:0 0 16px;font-weight:700}
.pt-bday{display:flex;align-items:center;gap:12px;background:linear-gradient(90deg,#FFE3E4,#EAF2FD);border:2px solid var(--y);border-radius:16px;padding:12px 14px;margin:0 0 16px;box-shadow:0 6px 16px rgba(227,36,43,.25)}
.pt-bday b{display:block;font:800 19px var(--fh)}.pt-bday small{color:var(--k2)}.pt-bday div{flex:1;min-width:0}
.bd-cake{font-size:38px;animation:bdb 1.6s ease-in-out infinite}@keyframes bdb{50%{transform:translateY(-5px) rotate(-6deg)}}
.bd-modal h2{font-size:28px;margin:8px 0}.bd-balloons{font-size:44px;letter-spacing:6px}.bd-age{font:800 20px var(--fh);color:var(--y)}
.pt-bask{display:flex;gap:12px;align-items:flex-start;margin:16px 0}.pt-bask b{display:block;font:800 18px var(--fh)}.pt-bask small{color:var(--mut)}
.pt-bask .row{margin-top:8px}.pt-bask .inp{max-width:220px;font-size:16px}
/* clases con profes (Premium) */
.lv-wrap{display:grid;gap:14px}
.lv-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.lv-st{background:#fff;border:1.5px solid var(--bd);border-radius:16px;padding:12px 10px;text-align:center;box-shadow:var(--sh);min-width:0}
.lv-st b{display:block;font:800 30px var(--fh)}.lv-st b small{font-size:16px;color:var(--mut)}
.lv-st span{display:block;font-weight:800;font-size:14px}.lv-st em{display:block;font-style:normal;font-size:12px;color:var(--mut)}
.lv-st.vip{background:#FFF1F1}.lv-st.grp{background:var(--y3)}
.lv-card{display:grid;gap:10px}.lv-card p{margin:0}
.lv-h{display:flex;gap:12px;align-items:center}.lv-h h3{font-size:20px;margin-top:4px}
.lv-ic{font-size:28px;width:50px;height:50px;flex:none;border:1.5px solid var(--bd);border-radius:14px;display:grid;place-items:center;background:var(--y3)}
