.ar-holes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;max-width:560px;margin:0 auto;background:#6aa84f;border:1.5px solid var(--bd);border-radius:20px;padding:12px;box-shadow:0 6px 18px rgba(11,42,91,.12);background-image:radial-gradient(rgba(255,255,255,.15) 2px,transparent 2px);background-size:18px 18px}
