.ar-well{position:relative;height:max(320px,calc(calc(100svh / var(--z, 1)) - 360px));overflow:hidden;border:1.5px solid var(--bd);border-radius:16px;background:linear-gradient(180deg,#0B2A5B 0%,#1C3F7A 100%);background-image:linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(180deg,#0B2A5B,#1C3F7A);background-size:34px 34px,34px 34px,auto;touch-action:manipulation}
.ar-wlimit{position:absolute;left:0;right:0;top:0;height:4px;background:repeating-linear-gradient(90deg,var(--y) 0 12px,transparent 12px 22px)}
.ar-junk{position:absolute;left:0;right:0;bottom:0;height:0;background:repeating-linear-gradient(0deg,#7a8aa6 0 30px,#0B2A5B 30px 34px);transition:height .3s}
