.ar-tbar2{min-height:54px;margin-top:8px;background:#fff;border:1.5px solid var(--bd);border-radius:14px;box-shadow:0 6px 18px rgba(11,42,91,.12);padding:8px;display:flex;flex-wrap:wrap;gap:6px;align-items:center}
