@media (min-width:760px){.ar-quiz{grid-template-columns:150px minmax(0,1fr)}.ar-ladder{grid-template-columns:1fr;display:flex;flex-direction:column-reverse;gap:4px}.ar-ladder span{display:flex;justify-content:space-between;padding:5px 10px;font-size:13px}.ar-ladder span i{display:inline}}
.ar-lifes{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.ar-life{border:1.5px solid var(--bd);border-radius:99px;background:var(--k);color:#fff;font:800 13px var(--fh);padding:8px 4px;box-shadow:0 6px 16px rgba(227,36,43,.25);min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ar-life.used{background:#cfd8e6;color:#7a879c;box-shadow:none;text-decoration:line-through}
.ar-qcard{margin:10px 0;padding:14px 16px;background:var(--k);color:#fff;border-color:var(--k);box-shadow:0 6px 16px rgba(227,36,43,.25)}
