.ar-qcard .muted{color:#cfe0ff!important}
.ar-qcard.ar-in{animation:arIn .35s}
.ar-qs u{text-decoration:none;color:#ffb3b6;letter-spacing:1px}
.ar-qopts{display:grid;gap:8px}
@media (min-width:600px){.ar-qopts{grid-template-columns:1fr 1fr}}
.ar-qo{display:flex;align-items:center;gap:10px;background:#fff;border:1.5px solid var(--bd);border-radius:99px;box-shadow:0 6px 18px rgba(11,42,91,.12);padding:10px 14px;text-align:left;font:700 17px var(--fb);color:var(--k);min-height:54px;min-width:0}
.ar-qo i{flex:none;font-style:normal;width:30px;height:30px;border-radius:50%;background:var(--y);color:#fff;display:grid;place-items:center;font:800 15px var(--fh)}
.ar-qo span{min-width:0;overflow-wrap:anywhere}
.ar-qo.sel{background:#ffd27a;animation:arPulse .6s infinite}
.ar-qo.gone{visibility:hidden}
.ar-aud{margin-top:10px;padding:12px}
.ar-audr{display:flex;align-items:center;gap:8px;margin-top:6px}
.ar-audr i{font-style:normal;font-weight:800;width:20px}
.ar-audr span{flex:1;height:16px;border:1.5px solid var(--bd);border-radius:99px;overflow:hidden;background:var(--y3)}
.ar-audr em{display:block;height:100%;background:var(--blue);animation:arGrow .8s ease-out}
/* 8) cohete de voz */
.ar-voice{display:grid;grid-template-columns:70px minmax(0,1fr);gap:12px}
.ar-sky2{position:relative;min-height:380px;border:1.5px solid var(--bd);border-radius:16px;overflow:hidden;background:linear-gradient(180deg,#0B2A5B 0%,#1D5FD1 60%,#cfe3ff 100%)}
.ar-sky2::before{content:"✦ · ✧ · ✦";position:absolute;top:8px;left:0;right:0;text-align:center;color:#fff;font-size:11px;letter-spacing:2px;opacity:.8}
.ar-stages{position:absolute;left:6px;top:8%;bottom:10px;display:flex;flex-direction:column-reverse;justify-content:space-between}
.ar-stages i{width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,.35);border:2px solid #fff}
.ar-stages i.on{background:var(--y)}
.ar-rocket{position:absolute;left:50%;bottom:8px;transform:translateX(-50%) rotate(-45deg);font-size:36px;transition:bottom .7s cubic-bezier(.3,1.4,.6,1)}
.ar-rocket.launch{bottom:120%!important;transition:bottom 1.4s ease-in}
.ar-pad{position:absolute;left:0;right:0;bottom:0;height:6px;background:var(--y)}
.ar-vcard{text-align:center;display:grid;gap:8px;justify-items:center;padding:14px}
.ar-vcard .ar-ph{width:100%;max-width:340px;aspect-ratio:4/3;height:auto;border-radius:14px;border:1.5px solid var(--bd)}
.ar-vw{font:800 clamp(26px,7vw,38px) var(--fh);overflow-wrap:anywhere}
.ar-mic.rec{background:var(--y);color:#fff;animation:arPulse .7s infinite}
.ar-vopts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;width:100%;max-width:360px}
.ar-vo.sel{background:var(--k);color:#fff}
.ar-vr{margin-top:10px;border:1.5px solid var(--bd);border-radius:14px;padding:10px 12px;font-weight:700;background:#fff;text-align:center}
.ar-vr small{display:block;font-weight:600;color:var(--mut);margin-top:4px}
.ar-vr.ok{background:var(--ok2);border-color:var(--ok)}.ar-vr.bad{background:var(--bad2);border-color:var(--bad)}.ar-vr.mid{background:#fff6dd}
.ar-link{display:block;margin:10px auto 0;background:none;border:0;color:var(--blue);font-weight:800;text-decoration:underline;font-size:14px}
@media (max-width:420px){.ar-voice{grid-template-columns:54px minmax(0,1fr);gap:8px}.ar-rocket{font-size:28px}}
/* 9) detective */
.ar-ecard{text-align:center;display:grid;gap:10px;justify-items:center;padding:16px}
.ar-ecard small{font-weight:800;color:var(--mut)}
.ar-ebig{width:150px;height:150px;border-radius:50%;border:1.5px solid var(--bd);background:var(--y);color:#fff;box-shadow:0 6px 18px rgba(11,42,91,.12);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px}
.ar-ebig span{font-size:52px;line-height:1}
.ar-ebig b{font:800 15px var(--fh)}
.ar-ebig.on{animation:arPulse .8s infinite}
.ar-eopts{display:grid;gap:10px;margin-top:12px}
.ar-eo{background:#fff;border:1.5px solid var(--bd);border-radius:14px;box-shadow:0 6px 18px rgba(11,42,91,.12);padding:12px 14px;font:700 17px var(--fb);color:var(--k);text-align:left;line-height:1.35;min-height:54px}
/* 10) desliza */
.ar-swipe{display:grid;justify-items:center}
.ar-sdeck{position:relative;width:100%;max-width:400px;height:300px;margin:6px 0 14px}
.ar-scard{position:absolute;inset:0;background:#fff;border:1.5px solid var(--bd);border-radius:24px;box-shadow:0 6px 18px rgba(11,42,91,.12);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:16px;gap:6px;touch-action:pan-y;user-select:none;transition:transform .28s ease,opacity .28s;animation:arDeal .3s ease-out;cursor:grab}
.ar-scard small{font-weight:800;color:var(--mut);font-size:13px}
.ar-scard b{font:800 clamp(24px,7vw,34px) var(--fh);line-height:1.15;overflow-wrap:anywhere}
.ar-scard b.long{font-size:clamp(19px,5vw,24px)}
.ar-seq{font:800 24px var(--fh);color:var(--y)}
.ar-scard p{margin:0;font-size:clamp(17px,4.6vw,21px);font-weight:700;color:var(--blue);overflow-wrap:anywhere}
.ar-stamp{position:absolute;top:18px;font-style:normal;font:800 22px var(--fh);border:3px solid;border-radius:10px;padding:2px 10px;opacity:0;transition:opacity .15s}
