.ar-scard.lean-r .ar-stamp.y,.ar-scard.out-r .ar-stamp.y{opacity:1}.ar-scard.lean-l .ar-stamp.n,.ar-scard.out-l .ar-stamp.n{opacity:1}
.ar-scard.out-r{transform:translateX(120%) rotate(18deg)!important;opacity:0}
