.ar-sbtns{display:flex;gap:28px}
.ar-sb{width:86px;height:86px;border-radius:50%;border:1.5px solid var(--bd);box-shadow:0 6px 18px rgba(11,42,91,.12);font:800 34px var(--fh);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1}
.ar-sb small{font-size:12px;margin-top:2px}
.ar-sb.no{background:var(--y)}.ar-sb.yes{background:var(--ok)}
.ar-sb:active{transform:translate(3px,3px);box-shadow:0 6px 18px rgba(11,42,91,.12)}
.ar-shint{font-size:13px;margin-top:10px}
.ar-sdeck{overflow:visible}
.ar-swipe{overflow:hidden;padding:4px}
/* animaciones */
@keyframes arIn{from{opacity:0;transform:translateY(14px) scale(.97)}to{opacity:1;transform:none}}
@keyframes arBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
@keyframes arTw{0%,100%{opacity:.25;transform:scale(.8) rotate(0)}50%{opacity:1;transform:scale(1.2) rotate(20deg)}}
@keyframes arPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
@keyframes arBump{0%{transform:scale(1)}40%{transform:scale(1.25)}100%{transform:scale(1)}}
@keyframes arShake{0%,100%{transform:translateX(0)}20%{transform:translateX(-6px)}40%{transform:translateX(6px)}60%{transform:translateX(-4px)}80%{transform:translateX(4px)}}
@keyframes arShakeX{0%,100%{margin-left:0}25%{margin-left:-6px}75%{margin-left:6px}}
@keyframes arCount{0%{transform:scale(2.2);opacity:0}60%{transform:scale(.9);opacity:1}100%{transform:scale(1)}}
@keyframes arPop{0%{opacity:0;transform:translate(-50%,-30%) scale(.6)}20%{opacity:1;transform:translate(-50%,-60%) scale(1.15)}100%{opacity:0;transform:translate(-50%,-160%) scale(1)}}
@keyframes arPt{to{transform:translate(var(--dx),var(--dy)) rotate(200deg);opacity:0}}
@keyframes arCombo{0%{opacity:0;transform:translate(-50%,-50%) scale(.4) rotate(-8deg)}25%{opacity:1;transform:translate(-50%,-50%) scale(1.1) rotate(3deg)}75%{opacity:1;transform:translate(-50%,-50%) scale(1)}100%{opacity:0;transform:translate(-50%,-90%) scale(.9)}}
@keyframes arBurst{to{opacity:0;scale:1.6}}
@keyframes arFade{to{opacity:0}}
@keyframes arTurbo{0%{filter:none}50%{filter:drop-shadow(-14px 0 0 #E3242B)}100%{filter:none}}
@keyframes arSpin{to{rotate:720deg}}
@keyframes arFlip{0%{transform:rotateX(90deg)}100%{transform:rotateX(0)}}
@keyframes arGrow{from{width:0}}
@keyframes arDeal{from{transform:translateY(30px) scale(.92);opacity:0}}
@media (prefers-reduced-motion:reduce){.ar-gc,.ar-hero-mra,.ar-md.on span,.ar-go,.ar-spark,.ar-feat{animation:none!important}}
