.itl{position:fixed;inset:0;z-index:9500;background:radial-gradient(circle at 50% 35%,#1d4c9c,#0B2A5B 70%);display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;cursor:pointer;animation:itlIn .25s ease}
