.itl-img{width:100%;height:auto;display:block;filter:drop-shadow(0 14px 18px rgba(0,0,0,.4))}
.itl-say{position:absolute;top:-34px;left:50%;transform:translateX(-50%);background:#fff;color:#0B2A5B;border:2px solid #E3242B;border-radius:16px;padding:4px 14px;font:800 18px Poppins,sans-serif;white-space:nowrap;z-index:2}
@keyframes itlFly{0%{transform:translateX(-120vw) rotate(-6deg)}30%{transform:translateX(0) rotate(3deg)}50%{transform:translateY(-14px) rotate(-2deg)}72%{transform:translateX(0) translateY(0)}100%{transform:translateX(130vw) rotate(6deg)}}
.itl-up .itl-actor{animation-name:itlUp}@keyframes itlUp{0%{transform:translate(-70vw,calc(70vh / var(--z, 1))) rotate(12deg)}35%{transform:translate(0,0) rotate(0)}70%{transform:translate(0,-14px)}100%{transform:translate(80vw,-90vh) rotate(12deg)}}
