@keyframes itlStage{0%{transform:scale(.3);opacity:0}18%{transform:scale(1.08);opacity:1}26%{transform:scale(1)}40%,60%,80%{transform:scale(1.03) rotate(-1.5deg)}50%,70%,90%{transform:scale(1) rotate(1.5deg)}100%{transform:scale(1)}}
