.itl-pop .itl-actor{animation-name:itlPop2}@keyframes itlPop2{0%{transform:scale(.2) rotate(-10deg);opacity:0}25%{transform:scale(1.06) rotate(2deg);opacity:1}35%,85%{transform:scale(1) rotate(0)}100%{transform:scale(1.04)}}
.itl-walk .itl-actor{animation-name:itlWalk}@keyframes itlWalk{0%{transform:translateX(-110vw)}35%,70%{transform:translateX(0)}50%{transform:translateX(0) translateY(-8px)}100%{transform:translateX(120vw)}}
.itl-next{position:absolute;bottom:9%;text-align:center;color:#fff}.itl-next small{display:block;letter-spacing:4px;font-weight:800;color:#ffd43b}.itl-next b{display:block;font:900 clamp(26px,7vw,40px) Poppins,sans-serif;animation:itlPopN .5s .6s both}.itl-next i{display:block;font-size:13px;opacity:.7;margin-top:6px;font-style:normal}
