/* Mr. Arrieta bailando debajo del video */
.dance{text-align:center;margin-top:12px}.dance-floor{position:relative;height:190px;border-radius:18px;background:radial-gradient(circle at 50% 0,#ffd43b55,transparent 60%),linear-gradient(#0B2A5B,#163f86);overflow:hidden;border:1.5px solid var(--bd)}
