.dance-mra{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);cursor:pointer}.dance-img{height:165px;width:auto;transform-origin:50% 100%}
.dn{position:absolute;bottom:40px;font-size:26px;opacity:0}.n1{left:18%}.n2{left:50%}.n3{right:18%}
.dance.on .dance-img{animation:dnc .5s ease-in-out infinite alternate}.dance.on .dn{animation:dnNote 2s linear infinite}.dance.on .n2{animation-delay:.7s}.dance.on .n3{animation-delay:1.3s}
