@keyframes dnc{0%{transform:rotate(-8deg) translateY(0) scaleY(1)}50%{transform:rotate(0) translateY(-14px) scaleY(1.03)}100%{transform:rotate(8deg) translateY(0) scaleY(.97)}}
@keyframes dnNote{0%{transform:translateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(-140px) rotate(25deg);opacity:0}}
@keyframes dnLight{50%{background:radial-gradient(circle at 30% 0,#E3242B66,transparent 60%),linear-gradient(#0B2A5B,#163f86)}}
