.vc{border-radius:22px;padding:16px;display:flex;flex-direction:column;gap:10px;position:relative;max-width:560px;margin:0 auto}
.vc.vc-hide{display:none}
.vc-in{display:flex;gap:12px;align-items:center}
.vc-mic{width:66px;height:66px;border-radius:50%;display:grid;place-items:center;flex:none;position:relative;border:0;cursor:pointer;color:#fff;transition:background .3s,transform .15s}
.vc-mic:active{transform:scale(.95)}.vc-mic:disabled{opacity:.6;cursor:default}
.vc-mic svg{width:28px;height:28px;position:relative;z-index:1}
.vc-rg{position:absolute;inset:-6px;border-radius:50%;border:2px solid currentColor;opacity:0;animation:vcRing 1.8s ease-out infinite}
.vc-rg+.vc-rg{animation-delay:.9s}
.vc.rec .vc-rg{animation-duration:1.1s}
@keyframes vcRing{0%{transform:scale(.92);opacity:.55}100%{transform:scale(1.45);opacity:0}}
.vc-tx{flex:1;min-width:0;text-align:left}
.vc-tx small{display:block;font:800 10.5px var(--fh);letter-spacing:.09em;opacity:.8;line-height:1.35}
.vc-tx b.vc-say{display:block;font:800 18px/1.3 var(--fh);margin:3px 0 2px;word-wrap:break-word}
.vc-tx em{display:block;font-style:normal;font-size:13px;opacity:.78}
.vc-tgt{font:inherit!important;margin:0!important;padding:0!important;background:none!important;border:0!important;text-align:left!important;color:inherit!important;min-height:0!important}
.vc-tgt .w.ok{color:#4ade80}.vc-tgt .w.no{color:#ff8a8f;text-decoration:underline}
.vc-ex{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;flex:none;border:0;cursor:pointer}
.vc-ex svg{width:21px;height:21px}
.vc-wv{display:flex;gap:3px;align-items:center;justify-content:center;height:46px}
.vc-wv i{display:block;width:4px;border-radius:4px;opacity:.55;transition:height .07s linear}
.vc-ft{display:flex;align-items:center;justify-content:center;gap:8px;font:700 12.5px var(--fh);opacity:.88}
.vc-dot{width:8px;height:8px;border-radius:50%}
.vc.rec .vc-dot{animation:rfBlink 1s steps(2) infinite}
/* adultos */
.vc-adult{background:linear-gradient(135deg,#0B2A5B,#1B4A9B);color:#fff;box-shadow:0 14px 30px -12px rgba(11,42,91,.6)}
.vc-adult .vc-mic{background:#E3242B;box-shadow:0 10px 20px -8px rgba(227,36,43,.9)}.vc-adult .vc-mic .vc-rg{color:#ff8a8f}
.vc-adult .vc-ex{background:rgba(255,255,255,.14);color:#fff}.vc-adult .vc-wv i{background:#fff}.vc-adult .vc-dot{background:#ff6b72}
.vc-adult.rec .vc-mic{background:#16a34a;box-shadow:0 10px 22px -8px rgba(22,163,74,.9)}.vc-adult.rec .vc-mic .vc-rg{color:#4ade80}
/* teens */
.vc-teens{background:#071a3a;border:1px solid #16376e;color:#e6eefc;box-shadow:0 0 24px rgba(34,229,138,.12)}
.vc-teens .vc-mic{background:radial-gradient(circle at 35% 30%,#3df5a1,#13b86b);color:#04122b;box-shadow:0 0 22px rgba(34,229,138,.5)}.vc-teens .vc-mic .vc-rg{color:#22e58a}
.vc-teens .vc-ex{background:#16376e;color:#22e58a}.vc-teens .vc-wv i{background:#22e58a;box-shadow:0 0 6px rgba(34,229,138,.7)}.vc-teens .vc-dot{background:#22e58a}
.vc-teens .vc-tx small{color:#22e58a;opacity:1}
/* kids */
.vc-kids{background:#fff;border:2.5px solid #fde3b4;color:#0B2A5B}
.vc-kids .vc-mic{background:radial-gradient(circle at 35% 30%,#fcd34d,#f59e0b);box-shadow:0 5px 0 #c47f08}.vc-kids .vc-mic .vc-rg{color:#f59e0b;border-width:3px}
.vc-kids .vc-ex{background:#fff3dc;color:#d97706}.vc-kids .vc-wv{gap:5px}.vc-kids .vc-wv i{width:7px}.vc-kids .vc-dot{background:#16a34a}
.vc-kids .vc-tx small{color:#d97706;opacity:1}
.vc-kids.rec .vc-mic{background:radial-gradient(circle at 35% 30%,#4ade80,#16a34a);box-shadow:0 5px 0 #11803a}
.vc-kids .vc-tgt .w.ok{color:#16a34a}.vc-kids .vc-tgt .w.no{color:#E3242B}
.vc-kr{display:flex;align-items:flex-end;gap:10px;max-width:560px;margin:0 auto 6px}
.vc-kr .mascot{height:118px;width:auto;flex:none;margin:0}
