#azwait i{width:14px;height:14px;border-radius:50%;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;animation:azspin .8s linear infinite}
@keyframes azspin{to{transform:rotate(360deg)}}
/* v512 · Opción A: sombra suave en el piso debajo de Mr. Arrieta (todas las edades) */
img.mra,img.ar-hero-mra,img.ar-res-mra{box-sizing:content-box;padding-bottom:6px;background:radial-gradient(closest-side,rgba(11,42,91,.30),rgba(11,42,91,.12) 55%,transparent) no-repeat 50% 100%/64% 16px}
img.ld-load-mra,img.kd-mra,img.ld-hero-mra,img.db-hero-mra{box-sizing:content-box;padding-bottom:22px;background:radial-gradient(closest-side,rgba(11,42,91,.26),rgba(11,42,91,.10) 55%,transparent) no-repeat 50% 100%/58% 16px}
.itl-actor::after{content:"";position:absolute;left:50%;bottom:-14px;transform:translateX(-50%);width:64%;height:20px;border-radius:50%;background:radial-gradient(closest-side,rgba(11,42,91,.34),rgba(11,42,91,.14) 50%,transparent);pointer-events:none;z-index:-1}
.itl-actor{z-index:0}
.itl-k-sad::after{bottom:-6px}[class*="itl-k-balloon"]::after{bottom:-34px;width:46%}
/* v516 · motor de melodía (sin reconocimiento de voz) */
.mel9{--mel9-me:#E3242B;--mel9-mo:#c3cddd;display:flex;flex-direction:column;gap:3px}
.mel9-cv{width:100%;height:clamp(46px,calc(7svh / var(--z, 1)),64px);display:block;background:#f6f8fc;border:1.5px solid #e3e9f3;border-radius:12px}
.mel9-lg{display:flex;gap:12px;font-size:11px;font-weight:700;color:#5a6b85}.mel9-lg i{display:inline-block;width:14px;height:4px;border-radius:2px;vertical-align:2px;margin-right:4px}.mel9-lg .mo{background:var(--mel9-mo)}.mel9-lg .me{background:var(--mel9-me)}
.mel9-res{display:flex;gap:6px;margin-top:4px}.mel9-res span{flex:1;background:#f6f8fc;border-radius:10px;padding:4px 8px;font-size:12px;font-weight:700;color:#5a6b85;white-space:nowrap}.mel9-res b{color:#f59e0b;letter-spacing:1px}.mel9-res i{color:#ddd3c2;font-style:normal}
.mel9-tip{margin:4px 0 0;font-size:13px;font-weight:600;color:#0B2A5B}
.mel9-bt{display:flex;gap:6px;margin-top:5px}.mel9-bt .btn{flex:1}
.dk .mel9,.teens .mel9{--mel9-me:#22e58a;--mel9-mo:#3b557f}.dk .mel9-cv{background:#12284f;border-color:#1e3a6b}.dk .mel9-res span{background:#12284f;color:#9fb3d1}.dk .mel9-tip{color:#fff}
.kids .mel9{--mel9-me:#d97706}
.lrc-res .mel9-lg{display:none}.lrc-res .mel9-cv{height:44px}.lrc-res .mel9-res{margin-top:3px}.lrc-res .mel9-res span{padding:3px 7px;font-size:11.5px}.lrc-res .mel9-tip{font-size:12.5px;margin-top:3px}.lrc-res .mel9-bt{margin-top:4px}.lrc-res .mel9-bt .btn{padding:6px 8px;font-size:12.5px}
@media(max-width:899px){.lrc-card:has(.mel9-res) .lrc-ph{max-height:calc(26svh / var(--z, 1))}}
/* v517 · misión = escena de doblaje según el objetivo */
.ms9{display:flex;flex-direction:column;gap:10px}
.ms9-sc{position:relative;height:clamp(110px,calc(20svh / var(--z, 1)),190px);border-radius:18px;background:#cfd8e6 center 40%/cover;display:flex;align-items:flex-end;justify-content:space-around;padding:0 10px 8px;overflow:hidden}
.ms9-sc:after{content:"";position:absolute;inset:40% 0 0;background:linear-gradient(transparent,rgba(8,20,45,.55))}
.ms9-goal{position:absolute;top:10px;left:10px;z-index:1;display:inline-flex;align-items:center;gap:6px;background:rgba(255,255,255,.92);color:#0B2A5B;border-radius:99px;padding:4px 10px;font:700 12px Inter,system-ui,sans-serif}.ms9-goal .mri{width:14px;height:14px}
.ms9-ch{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:4px;transition:transform .2s}
.ms9-av{width:clamp(52px,calc(8svh / var(--z, 1)),72px);height:clamp(52px,calc(8svh / var(--z, 1)),72px);border-radius:50%;overflow:hidden;border:3px solid #fff;box-shadow:0 6px 14px rgba(0,0,0,.2);background:#fff;display:grid;place-items:center}.ms9-av img{width:100%;height:100%;object-fit:cover}
.ms9-av.ini{background:#0B2A5B;color:#fff;font:800 20px Poppins,sans-serif}.ms9-ch.me .ms9-av{outline:3px solid #E3242B;outline-offset:2px}
.ms9-ch small{background:#E3242B;color:#fff;font:700 11px Inter;border-radius:99px;padding:1px 9px}
.ms9-ch.talk{transform:translateY(-6px)}.ms9-ch.talk .ms9-av{box-shadow:0 0 0 6px rgba(245,158,11,.4)}
.ms9-sit{font-size:13px;color:#5a6b85;font-weight:600}.ms9-sit:empty{display:none}
.ms9-dl{display:flex;flex-direction:column;gap:6px;max-height:calc(24svh / var(--z, 1));overflow:auto}
.ms9-b{max-width:86%;background:#f1f4f9;border-radius:14px;padding:8px 12px;font-size:14.5px;font-weight:600;color:#0B2A5B}.ms9-b small{display:block;font-weight:500;color:#5a6b85;font-size:12.5px}
.ms9-b.me{align-self:flex-end;background:#fff;border:1.5px solid #E3242B}.ms9-b em{color:#f59e0b;font-style:normal;font-size:12px;margin-left:6px}.ms9-b.now{box-shadow:0 0 0 3px #f59e0b}
.ms9-q{margin:0;font:800 16px Poppins,sans-serif}.ms9-opts{display:flex;flex-direction:column;gap:7px}
.ms9-o{text-align:left;border:1.5px solid #dbe3ef;background:#fff;border-radius:12px;padding:11px 12px;font:600 14.5px Inter,system-ui,sans-serif;color:#0B2A5B;cursor:pointer}.ms9-o.bad{border-color:#E3242B;animation:ms9sh .4s}
@keyframes ms9sh{25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}
.ms9-rep{align-self:flex-start;border:0;background:none;color:#5a6b85;font:700 13px Inter;display:inline-flex;gap:6px;align-items:center;cursor:pointer}.ms9-rep .mri{width:16px;height:16px}
.ms9-turn{display:flex;flex-direction:column;gap:8px}
.ms9-line{background:#0B2A5B;color:#fff;border-radius:14px;padding:10px 13px}.ms9-line small{display:block;font:700 10.5px Inter;letter-spacing:.08em;color:#ffd43b;margin-bottom:3px}.ms9-line b{font:800 19px Poppins,sans-serif}.ms9-line span{display:block;font-size:12.5px;color:#c9d6ea;margin-top:2px}
.ms9-act{display:flex;align-items:center;gap:12px}.ms9-act>div{flex:1}.ms9-act b{display:block;font-size:14.5px}.ms9-act small{color:#5a6b85;font-size:12.5px}
.ms9-mic{width:58px;height:58px;border-radius:50%;border:0;background:#E3242B;color:#fff;display:grid;place-items:center;flex:none;cursor:pointer;box-shadow:0 0 0 7px rgba(227,36,43,.15)}.ms9-mic .mri{width:24px;height:24px}.ms9-mic.rec{animation:vk2rec 1.2s infinite}
.ms9-bt{display:flex;gap:8px}.ms9-bt .btn{flex:1}
.ms9-fin b{display:block;font:800 19px Poppins,sans-serif}.ms9-fin span{font-size:13.5px;color:#5a6b85}.ms9-fin i{color:#f59e0b;font-style:normal}.ms9-fin i i{color:#ddd3c2}
.dk .ms9-b{background:#12284f;color:#fff}.dk .ms9-b small,.dk .ms9-sit,.dk .ms9-act small,.dk .ms9-fin span{color:#9fb3d1}.dk .ms9-b.me{background:#0B1E3F;border-color:#22e58a}.dk .ms9-o{background:#12284f;border-color:#1e3a6b;color:#fff}.dk .ms9-line{background:#081733}.dk .ms9-line small{color:#22e58a}.dk .ms9-mic{background:#22e58a;color:#0B1E3F}.dk .ms9-ch.me .ms9-av{outline-color:#22e58a}.dk .ms9-ch small{background:#22e58a;color:#0B1E3F}.dk .ms9-q,.dk .ms9-fin b{color:#fff}
.mel9-res.no span{opacity:.75}.vk-fb.mel{display:block;background:rgba(255,255,255,.96);color:#0B2A5B;border-radius:12px;padding:8px}
/* v517 · escucha y toca la letra */
.lt9{display:flex;flex-direction:column;gap:12px}.lt9-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.lt9-n{font-weight:800;font-size:14px}
.lt9-g{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.lt9-b{border:1.5px solid #dbe3ef;background:#fff;border-radius:14px;padding:16px 0;font:800 26px Poppins,sans-serif;color:#0B2A5B;cursor:pointer}
.lt9-b.ok{background:#17a35a;border-color:#17a35a;color:#fff}.lt9-b.bad{border-color:#E3242B;animation:ms9sh .4s}.lt9-fb{margin:0;min-height:20px;font-weight:700;font-size:14px;text-align:center}
.dk .lt9-b{background:#12284f;border-color:#1e3a6b;color:#fff}
.khw:has(.khw-say[style*="none"]){grid-template-columns:1fr}
/* v517 · completar lo personal escribiendo */
.bl9{display:flex;flex-direction:column;gap:8px}.bl9 small{font-weight:700;color:#5a6b85;font-size:12.5px}.bl9-r{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-weight:700;font-size:16px}.bl9-i{flex:1;min-width:120px;font-size:16px;padding:8px 10px}.bl9-ok{align-self:flex-start}
.dk .bl9 small{color:#9fb3d1}.dk .bl9-r{color:#fff}
.rl-mel,.kw-mel,.lp-mel{margin-top:8px}
/* v518 · repetir la frase si quiere */
.rp9{display:flex;gap:6px;margin-top:8px}.rp9 .btn{flex:1;padding:8px 6px;font-size:13px}
/* ===== v519 · MÓDULO 2 · experiencia propia ===== */
.m2x-adult{--m2a:#0E5E6F;--m2b:#C8A24B;--m2i:#0B2A3B;--m2s:#eef5f6}
.m2x-teens{--m2a:#7C5CFF;--m2b:#22E39A;--m2i:#0f1430;--m2s:#1a2147}
.m2x-kids{--m2a:#0F8A6A;--m2b:#F59E0B;--m2i:#0B2A3B;--m2s:#eef8f3}
.m2x .phead .prog i{background:var(--m2a)!important}
.m2x-st .mel9{--mel9-me:var(--m2a)}
.m2v-card{background:var(--m2i);color:#fff;border-radius:14px;padding:11px 14px;display:flex;flex-direction:column;gap:3px}
.m2v-card small{font-size:11px;font-weight:800;letter-spacing:.08em;color:var(--m2b)}.m2v-card b{font-size:19px;line-height:1.25}.m2v-card span{font-size:13px;opacity:.8}
.m2v-card .bl9-r{color:#fff}.m2v-card .bl9-i{color:#111}
.m2v-mel{margin-top:8px}.m2v-res{min-height:4px}
.m2v-row{display:flex;align-items:center;gap:10px;margin-top:8px}
.m2v-mic{width:56px;height:56px;flex:none;border-radius:50%;border:0;background:var(--m2a);color:#fff;display:grid;place-items:center;cursor:pointer;box-shadow:0 6px 16px rgba(0,0,0,.18)}
.m2v-mic svg{width:24px;height:24px}.m2v-mic.rec{background:#E3242B;animation:m2pulse 1s infinite}
.m2v-st{flex:1;display:flex;flex-direction:column;line-height:1.2}.m2v-st b{font-size:15px}.m2v-st small{font-size:12px;opacity:.7}
.m2v-row .m2v-mo{flex:none}
.m2v-ptt{flex:1;display:flex;align-items:center;justify-content:center;gap:10px;min-height:56px;border:0;border-radius:999px;background:var(--m2a);color:#fff;font-weight:800;font-size:15px;cursor:pointer;user-select:none;-webkit-user-select:none;touch-action:none}
.m2v-ptt svg{width:22px;height:22px}.m2v-ptt.rec{background:#E3242B;transform:scale(.98);animation:m2pulse 1s infinite}
@keyframes m2pulse{0%{box-shadow:0 0 0 0 rgba(227,36,43,.45)}100%{box-shadow:0 0 0 14px rgba(227,36,43,0)}}
.m2-sum{text-align:center;padding:14px;border-radius:14px;background:var(--m2s)}.m2-sum b{display:block;font-size:30px;color:var(--m2a)}.m2-sum span{font-size:14px;opacity:.8}
/* llamada */
.m2c{display:flex;flex-direction:column;gap:10px}
.m2c-top{background:linear-gradient(160deg,var(--m2a),var(--m2i));color:#fff;border-radius:18px;padding:14px;display:flex;flex-direction:column;align-items:center;gap:4px;position:relative}
.m2c-av{width:74px;height:74px;border-radius:50%;background:#ccc center/cover;border:3px solid rgba(255,255,255,.85)}
.m2c.live .m2c-av{box-shadow:0 0 0 0 rgba(255,255,255,.5)}.m2c.talk .m2c-av{animation:m2ring 1s infinite}
@keyframes m2ring{0%{box-shadow:0 0 0 0 rgba(200,162,75,.7)}100%{box-shadow:0 0 0 16px rgba(200,162,75,0)}}
.m2c-top b{font-size:18px}.m2c-t{font-size:12.5px;opacity:.85}.m2c.ended .m2c-top{filter:grayscale(.5)}
.m2c-q{display:flex;gap:10px;align-items:center;background:var(--m2s);border-radius:14px;padding:10px 12px}.m2c-q:empty{display:none}
.m2c-q b{font-size:16px;display:block}.m2c-q small{font-size:12.5px;opacity:.7}
.m2c-ql,.m2l-pl,.m2w-pl,.m2m-pl{border:0;background:var(--m2a);color:#fff;border-radius:50%;width:34px;height:34px;flex:none;display:grid;place-items:center;cursor:pointer}.m2c-ql svg,.m2l-pl svg,.m2w-pl svg{width:17px;height:17px}
.m2c-dots{display:flex;gap:6px;justify-content:center}.m2c-dots i{width:8px;height:8px;border-radius:50%;background:#cfd9de}.m2c-dots i.cur{background:var(--m2b)}.m2c-dots i.ok{background:var(--m2a)}
/* live */
.m2l{display:flex;flex-direction:column;gap:10px}
.m2l-sc{position:relative;height:clamp(170px,calc(30svh / var(--z, 1)),240px);border-radius:16px;background:#222 center/cover;overflow:hidden}
.m2l-sc::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.15),rgba(0,0,0,.65))}
.m2l-badge{position:absolute;z-index:2;top:10px;left:10px;background:#E3242B;color:#fff;font-weight:800;font-size:12px;padding:3px 9px;border-radius:6px;display:flex;align-items:center;gap:5px}.m2l-badge i{width:7px;height:7px;border-radius:50%;background:#fff;animation:m2blink 1s infinite}
@keyframes m2blink{50%{opacity:.2}}
.m2l-v{position:absolute;z-index:2;top:10px;left:78px;background:rgba(0,0,0,.55);color:#fff;font-size:12px;font-weight:700;padding:3px 8px;border-radius:6px}
.m2l-cm{position:absolute;z-index:2;left:10px;right:10px;bottom:10px;display:flex;flex-direction:column;gap:6px;align-items:flex-start}
.m2l-c{background:rgba(10,12,30,.72);backdrop-filter:blur(4px);color:#fff;font-size:14px;padding:6px 10px;border-radius:12px;display:flex;align-items:center;gap:6px;animation:m2in .3s}
.m2l-c b{color:var(--m2b)}.m2l-c.me{background:var(--m2a)}.m2l-c.me b{color:#fff}.m2l-c.h{font-size:12.5px;opacity:.85}
.m2l-c .m2l-pl{width:26px;height:26px}.m2l-ok svg{width:15px;height:15px}
@keyframes m2in{from{opacity:0;transform:translateY(8px)}}
.m2l-es{margin:0;font-size:13px;opacity:.7}
/* walkie-talkie */
.m2w{display:flex;flex-direction:column;gap:10px}
.m2w-top{display:flex;align-items:flex-end;gap:8px}.m2w-mr{height:clamp(96px,calc(16svh / var(--z, 1)),130px);flex:none}
.m2w-b{position:relative;flex:1;background:#fff;border:2px solid var(--m2a);border-radius:16px 16px 16px 4px;padding:10px 44px 10px 12px;margin-bottom:12px}
.m2w-b b{font-size:17px;display:block}.m2w-b small{font-size:12.5px;opacity:.7}.m2w-b .m2w-pl{position:absolute;right:8px;top:50%;transform:translateY(-50%)}
.m2w-radio{position:relative;background:#26313a;border-radius:20px;padding:30px 12px 12px;box-shadow:inset 0 -4px 0 rgba(0,0,0,.25)}
.m2w-radio::before{content:'';position:absolute;top:-26px;right:30px;width:10px;height:30px;background:#26313a;border-radius:5px 5px 0 0}
.m2w-ch{position:absolute;top:8px;left:14px;font-size:11px;font-weight:800;letter-spacing:.1em;color:#9fb3c0}
.m2w-led{position:absolute;top:10px;right:14px;width:10px;height:10px;border-radius:50%;background:#46535c}.m2w-led.rx{background:#22c55e;box-shadow:0 0 8px #22c55e}
.m2w-radio .m2v-card{background:#3a4650}.m2w-radio .mel9-cv{background:#eef3f0}.m2w-radio .mel9-lg,.m2w-radio .mel9-tip,.m2w-radio .mel9-res{color:#e8eef2}
.m2w-st{display:flex;gap:6px;justify-content:center}.m2w-st i{width:22px;height:8px;border-radius:4px;background:#d6e0dc}.m2w-st i.on{background:var(--m2b)}.m2w-st i.off{background:#c8ced3}
/* agenda */
.m2a{display:flex;flex-direction:column;gap:12px}
.m2a-tl{display:flex;flex-direction:column;gap:6px;border-left:3px solid var(--m2a);padding-left:10px}
.m2a-s{display:flex;align-items:center;gap:10px;text-align:left;border:1.5px dashed #b9cbd1;background:#fff;border-radius:12px;padding:9px 12px;min-height:46px;cursor:pointer;font:inherit;color:inherit}
.m2a-s.on{border-style:solid;border-color:var(--m2a);background:var(--m2s)}.m2a-s.m2a-good{border-color:#16a34a;background:#ecfdf3}.m2a-s.m2a-bad{border-color:#E3242B;background:#fff1f1}
.m2a-n{width:24px;height:24px;border-radius:50%;background:var(--m2a);color:#fff;font-weight:800;font-size:13px;display:grid;place-items:center;flex:none}
.m2a-x{font-size:14.5px;color:#6b7a86}.m2a-s.on .m2a-x{color:var(--m2i)}.m2a-d{display:inline-block;font-weight:800;color:var(--m2a);margin-right:8px;font-variant-numeric:tabular-nums}
.m2a-cards{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.m2a-c{border:1.5px solid #d4e0e4;background:#fff;border-radius:12px;padding:10px;text-align:left;cursor:pointer;font:inherit;color:var(--m2i);display:flex;flex-direction:column;gap:2px;box-shadow:0 2px 0 #d4e0e4}
.m2a-c b{font-size:15px}.m2a-c small{font-size:12px;opacity:.65;display:flex;align-items:center;gap:4px}.m2a-c small svg{width:13px;height:13px}.m2a-c.used{opacity:.3;pointer-events:none}
.m2a-fb .btn{width:100%}
/* speed clock */
.m2s{display:flex;flex-direction:column;gap:12px}
.m2s-h{display:flex;justify-content:space-between;font-size:13px;font-weight:700;opacity:.85}.m2s-h b{color:var(--m2b)}
.m2s-tm{height:8px;border-radius:4px;background:rgba(255,255,255,.12);overflow:hidden}.m2s-tm i{display:block;height:100%;width:100%;background:var(--m2b);border-radius:4px}.m2s-tm i.lo{background:#ff5d6c}
.m2s-d{text-align:center;font-size:clamp(54px,14vw,76px);font-weight:900;letter-spacing:.04em;color:var(--m2b);font-variant-numeric:tabular-nums;text-shadow:0 0 24px rgba(34,227,154,.35)}
.m2s-o{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.m2s-b{border:1.5px solid rgba(255,255,255,.18);background:rgba(255,255,255,.06);color:#fff;border-radius:12px;padding:13px 8px;font:inherit;font-weight:700;font-size:14.5px;cursor:pointer}
.m2s-b.ok{border-color:var(--m2b);background:rgba(34,227,154,.15);color:var(--m2b)}.m2s-b.bad{border-color:#ff5d6c;background:rgba(255,93,108,.15)}
.m2s-fb{text-align:center;min-height:22px}.m2s-cb{color:var(--m2b);font-size:18px}
/* reloj mágico y reloj base */
.m2m{display:flex;flex-direction:column;gap:10px;align-items:stretch}
.m2m-h{display:flex;justify-content:space-between;align-items:center;font-size:13px;font-weight:800;color:var(--m2a)}
.m2m-pl{width:auto;border-radius:999px;padding:0 12px;gap:6px;display:flex;font-weight:700}.m2m-pl svg{width:16px;height:16px}
