body.fm-page .fm-hart::after{content:'';position:absolute;left:50%;bottom:-6px;width:70%;height:10px;margin-left:-35%;border-radius:50%;background:radial-gradient(ellipse,rgba(11,42,91,.38),rgba(11,42,91,0) 70%);filter:blur(1px);animation:fmSh 3.4s ease-in-out infinite;pointer-events:none;z-index:-1}
